  'This course prepares students to analyze, design, execute, measure, and improve marketing for hotels, resorts, restaurants, clubs, events, attractions, and related service organizations. Students use consumer research and market intelligence to select targets, position brands, design offers and guest journeys, coordinate integrated communications, manage digital and distribution channels, build CRM and loyalty programs, evaluate pricing and promotions, protect reputation, and allocate resources using experiments and financial evidence. U.S. truth-in-advertising, review, privacy, accessibility, and AI governance issues are embedded throughout, with global and cultural contexts considered where relevant.',
  $hmktjson${"slug": "hospitality-marketing", "title": "Hospitality Marketing", "description": "This course prepares students to analyze, design, execute, measure, and improve marketing for hotels, resorts, restaurants, clubs, events, attractions, and related service organizations. Students use consumer research and market intelligence to select targets, position brands, design offers and guest journeys, coordinate integrated communications, manage digital and distribution channels, build CRM and loyalty programs, evaluate pricing and promotions, protect reputation, and allocate resources using experiments and financial evidence. U.S. truth-in-advertising, review, privacy, accessibility, and AI governance issues are embedded throughout, with global and cultural contexts considered where relevant.", "topics": [{"id": "b7b1856c-b6f6-441b-af29-5042d2f550e3", "type": "topic", "title": "Hospitality Marketing, Service Logic, and Strategic Value", "description": "Hospitality marketing creates and communicates value before, during, and after a guest experience. This section frames marketing as an enterprise discipline that connects guest needs, operations, revenue, brand promises, and long-term relationships.", "children": [{"id": "1e39d3f3-1529-4471-8bcf-12935d4672dd", "type": "subtopic", "title": "Services-marketing fundamentals", "children": [{"id": "3b4dfac1-415c-488f-8d49-d7fb6aa60e81", "type": "concept", "title": "Intangibility, inseparability, variability, perishability, ownership, and perceived risk"}, {"id": "300b4877-6474-434e-8ca0-9d6f30ea8641", "type": "concept", "title": "The expanded service mix: product, price, place, promotion, people, process, and physical evidence"}, {"id": "0b842042-4e79-4073-b88d-b809aa9b076a", "type": "concept", "title": "Expectation formation, moments of truth, service scripts, signaling, guarantees, and recovery"}], "description": "Students learn why intangible, variable, perishable, and co-produced experiences require different choices from packaged goods."}, {"id": "a3a34072-f8e9-4ace-b7c7-00795a3f1d56", "type": "subtopic", "title": "Market orientation and value creation", "children": [{"id": "fe34511f-b883-40f5-a63f-3418c9ceb18c", "type": "concept", "title": "Customer orientation, competitor orientation, cross-functional coordination, learning, and responsiveness"}, {"id": "c25b2c86-a1df-4390-ba5c-894338219478", "type": "concept", "title": "Customer value, benefits, sacrifices, jobs-to-be-done, differentiation, parity, and switching costs"}, {"id": "ebdc000b-6a26-4ad7-b01c-761fb85bbff6", "type": "concept", "title": "Mission, objectives, capabilities, constraints, stakeholder value, and marketing's role in profitable demand"}], "description": "This subtopic turns guest, competitor, and operational evidence into a coherent value proposition and strategic direction."}, {"id": "94da44da-efab-478d-9492-14ecf3251873", "type": "subtopic", "title": "Hospitality sectors and business models", "children": [{"id": "4768925b-e8d9-4c5a-99b4-5ad0d5befca1", "type": "concept", "title": "Hotels, resorts, restaurants, vacation rentals, clubs, casinos, cruises, venues, and destinations"}, {"id": "787c1520-03c1-44fb-aeaf-46b34353a35e", "type": "concept", "title": "Owned, managed, franchised, licensed, independent, platform, membership, and asset-light models"}, {"id": "239fd64c-5583-43ce-a3c9-37c60f2a2c2a", "type": "concept", "title": "Demand perishability, fixed capacity, seasonality, ancillary revenue, labor intensity, and network effects"}], "description": "Students compare how marketing economics change across lodging, foodservice, clubs, events, attractions, travel, and destinations."}]}, {"id": "108b2414-4178-4370-bb5b-ccf90920ab37", "type": "topic", "title": "Consumer Behavior, Research, and Market Intelligence", "description": "Strong hospitality marketing starts with disciplined curiosity about people, context, and demand. Students learn to replace assumptions with evidence while respecting research ethics and the limits of available data.", "children": [{"id": "11c715ec-ad2f-4750-ba22-7ee221ec2171", "type": "subtopic", "title": "Guest decision behavior", "children": [{"id": "9719617d-14d4-4749-8feb-89dab219148d", "type": "concept", "title": "Need recognition, information search, consideration sets, booking, consumption, evaluation, sharing, and repeat behavior"}, {"id": "d525f9cb-4019-41f0-8e94-fd78b91a8624", "type": "concept", "title": "Functional, emotional, social, sensory, experiential, and transformative benefits"}, {"id": "3d9808b3-20e6-4e20-a92c-beee19b6834f", "type": "concept", "title": "Reference groups, household roles, culture, identity, accessibility needs, travel party, occasion, and situational factors"}], "description": "Students examine how motivation, perception, memory, emotion, culture, social influence, and risk shape hospitality choice and evaluation."}, {"id": "d2f1d090-0c00-45d3-9e59-febc163cb713", "type": "subtopic", "title": "Marketing research design", "children": [{"id": "02c8ef66-2e92-4017-b6ca-cdb7960d1140", "type": "concept", "title": "Decision problem, research question, hypotheses, constructs, measures, sampling, and analysis plan"}, {"id": "49eba0c6-cab6-43cd-93c8-a1ec827abc58", "type": "concept", "title": "Exploratory, descriptive, causal, qualitative, quantitative, observational, survey, interview, focus group, and experiment methods"}, {"id": "1d7043a7-3647-4886-b9d1-7d2fb7f0e449", "type": "concept", "title": "Validity, reliability, bias, confounding, nonresponse, representativeness, triangulation, and ethical consent"}], "description": "This subtopic develops the ability to turn a managerial problem into an answerable research question and credible evidence plan."}, {"id": "c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db", "type": "subtopic", "title": "Market and competitor intelligence", "children": [{"id": "5b208697-c7ad-45b4-a432-587592053cf0", "type": "concept", "title": "Market size, growth, share, penetration, demand drivers, seasonality, source markets, and trip purpose"}, {"id": "967a7828-9358-48d2-af59-2c4e60566810", "type": "concept", "title": "Competitive sets, rate/product audits, review mining, social listening, search trends, and mystery shopping"}, {"id": "de45dc19-a114-4917-bd14-26f3012961ee", "type": "concept", "title": "PESTLE, five forces, scenario signals, source quality, freshness, comparability, and uncertainty"}], "description": "Students assemble demand, competitor, channel, trend, and internal evidence without confusing a benchmark with a strategy."}]}, {"id": "894704ee-4042-42a2-a1af-ea09c90d1c94", "type": "topic", "title": "Segmentation, Targeting, Positioning, and Personas", "description": "Segmentation concentrates resources on meaningfully different needs and behaviors. Students learn to select attractive targets and create a position that can be delivered consistently—not merely write colorful personas.", "children": [{"id": "ab636d9c-a303-41e8-95d6-c66f33751f02", "type": "subtopic", "title": "Segmentation design", "children": [{"id": "9098ff59-7d8c-4e98-bfbc-47a03500ad6f", "type": "concept", "title": "Geographic, demographic, psychographic, behavioral, occasion, benefit, needs-based, firmographic, and value segments"}, {"id": "bfebd93d-6add-4875-99fd-7d770f90bf73", "type": "concept", "title": "Individual traveler, household, group, corporate account, intermediary, event planner, member, and local resident units"}, {"id": "b519365b-6d89-4b8f-a180-2064846b0951", "type": "concept", "title": "Identifiability, substantiality, stability, accessibility, differentiability, actionability, privacy, and fairness"}], "description": "Students divide markets using variables that predict needs, choice, value, or response and that managers can actually reach and serve."}, {"id": "c13fd011-6e5a-4e5d-afae-5dae53f23eee", "type": "subtopic", "title": "Target-market selection", "children": [{"id": "8834b530-0881-432f-a940-73aec35dda93", "type": "concept", "title": "Market potential, growth, competition, price sensitivity, acquisition cost, retention, ancillary spend, and seasonality"}, {"id": "d931f311-4d7e-432c-aae5-b2a9d55d2c1c", "type": "concept", "title": "Undifferentiated, differentiated, concentrated, local, niche, account-based, and one-to-one strategies"}, {"id": "7adff2e8-37bd-413a-92ed-6abb968bdbea", "type": "concept", "title": "Primary, secondary, exclusion, priority, capacity allocation, cannibalization, and portfolio balance"}], "description": "This subtopic compares segment attractiveness with strategic fit, cost to serve, capacity, risk, and likely lifetime economics."}, {"id": "56f7a2fe-7d2a-4526-9065-b4efc5f10b85", "type": "subtopic", "title": "Positioning and evidence-based personas", "children": [{"id": "7399b8a4-95e5-42f8-b6df-4db6f98a878a", "type": "concept", "title": "Frame of reference, target, insight, benefit, points of difference, points of parity, proof, and brand essence"}, {"id": "4d0665a4-cbc1-4f59-8f1e-0fdca3b4ba62", "type": "concept", "title": "Perceptual maps, value curves, positioning statements, message hierarchy, and competitive response"}, {"id": "9b6b099f-9de0-4ec3-bb77-6169a840b3e7", "type": "concept", "title": "Persona goals, behaviors, barriers, context, evidence, uncertainty, anti-stereotyping, and update cadence"}], "description": "Students turn research into a differentiated promise, reasons to believe, and practical decision tools for teams."}]}, {"id": "d648e2ca-b80c-4f49-b9ea-28ebdf942862", "type": "topic", "title": "Brand Strategy, Architecture, and Experience Design", "description": "A hospitality brand is a memory structure and an operating promise. This section connects identity and communications to standards, spaces, people, technology, partnerships, and the economics of a brand portfolio.", "children": [{"id": "bcf956a0-29ab-4c70-9010-2be331fa8fb7", "type": "subtopic", "title": "Brand identity and equity", "children": [{"id": "71665230-8a6a-4fe3-8ede-2fbaf45b7f24", "type": "concept", "title": "Purpose, values, personality, voice, visual identity, symbols, sensory codes, story, and heritage"}, {"id": "afcb6a7f-c2d9-4394-91c1-063e84bc8872", "type": "concept", "title": "Salience, imagery, judgments, feelings, resonance, familiarity, distinctiveness, and mental availability"}, {"id": "528ff1ae-f674-43fc-a802-562b52766cea", "type": "concept", "title": "Brand tracking, preference, consideration, price premium, advocacy, reputation, and financial contribution"}], "description": "Students learn how awareness, associations, perceived quality, trust, meaning, and loyalty create preference and pricing power."}, {"id": "4cae028c-d45e-421f-b245-f4a655e8db8a", "type": "subtopic", "title": "Brand architecture and portfolios", "children": [{"id": "fef01e6e-3265-41eb-a3b6-07b3b4e392c6", "type": "concept", "title": "Branded house, house of brands, endorsed brands, soft brands, collections, and independent affiliation"}, {"id": "956b4397-e138-4fca-9b36-5229d1a8d8e0", "type": "concept", "title": "Segment coverage, overlap, cannibalization, extension, licensing, franchising, conversion, and brand standards"}, {"id": "209f137b-363e-4663-aab9-b3a07b53a6e8", "type": "concept", "title": "Owner, operator, brand, franchisee, destination, chef, venue, and co-brand governance"}], "description": "This subtopic clarifies relationships among corporate, master, endorsed, collection, sub-brand, property, outlet, and partner brands."}, {"id": "c213da86-9bd3-4c61-97aa-32d902376ad3", "type": "subtopic", "title": "Experience and physical-evidence design", "children": [{"id": "205f4e15-0f3a-4591-91f5-30f8b51ae0b4", "type": "concept", "title": "Servicescape, atmosphere, sensory design, signage, collateral, uniforms, interface, accessibility, and wayfinding"}, {"id": "2f17aa85-67fb-4444-930d-cd95d6520b08", "type": "concept", "title": "Brand standards, service rituals, scripts, personalization, local authenticity, employee enablement, and empowerment"}, {"id": "b8c2a201-57ba-4332-806f-e8c6a9f508b3", "type": "concept", "title": "Concept testing, prototyping, blueprinting, consistency, adaptation, maintenance, and experience measurement"}], "description": "Students translate positioning into the visible and invisible cues that make the promise credible at every touchpoint."}]}, {"id": "2d9aeef6-0613-4fc9-bd30-c2f79ec377b4", "type": "topic", "title": "Customer Journey, Service Quality, and Inclusive Experience", "description": "Journey management reveals how many teams and platforms shape one guest relationship. Students diagnose friction, design accessible experiences, and close the loop between promised and delivered service.", "children": [{"id": "70d1f169-2e31-4e06-99a4-762f050d5517", "type": "subtopic", "title": "Journey mapping and service blueprinting", "children": [{"id": "b923be61-a9f2-438d-86a2-b0b48975b539", "type": "concept", "title": "Dreaming, planning, search, booking, pre-arrival, arrival, stay/visit, departure, post-stay, and return"}, {"id": "963f434b-856b-410e-8445-40e1a78914eb", "type": "concept", "title": "Touchpoints, moments of truth, pain points, delight, effort, wait, uncertainty, handoffs, and channel switching"}, {"id": "2a6781e0-274a-49ed-b36b-1eb901e29d49", "type": "concept", "title": "Frontstage, backstage, support process, data flow, ownership, service standards, and recovery triggers"}], "description": "Students map guest goals, actions, emotions, channels, handoffs, backstage processes, systems, and failure points."}, {"id": "fae7bdfe-0261-4eff-b31d-5c4685f4a677", "type": "subtopic", "title": "Service quality and experience measurement", "children": [{"id": "1aa02b63-b02d-47af-ad18-ca4b1a916d3d", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, tangibles, outcome quality, process quality, and value"}, {"id": "f33dd84c-fc15-4e70-8631-5780344ba8a5", "type": "concept", "title": "Satisfaction, overall rating, recommendation, effort, sentiment, complaints, repeat intent, and observed behavior"}, {"id": "088ae46a-6169-49db-8954-1c984d9af5ff", "type": "concept", "title": "Expectation effects, survey timing, scale design, response bias, benchmarks, drivers, and qualitative context"}], "description": "This subtopic combines perception and operational evidence to understand whether the experience met relevant expectations."}, {"id": "5a72cb61-340d-43c4-929c-1fa41ddcd8f1", "type": "subtopic", "title": "Accessibility, inclusion, and cultural intelligence", "children": [{"id": "19aafbfa-5923-4d16-a3f9-a4d5cf7ae9ff", "type": "concept", "title": "Universal design, accessible websites/content, captions, alt text, contrast, readable language, and assistive technology"}, {"id": "954b1d6c-c4df-4dea-9273-7251d5643af8", "type": "concept", "title": "Mobility, sensory, cognitive, dietary, allergy, religious, family, gender, language, and financial considerations"}, {"id": "ddf405c6-179c-4e54-ba64-16f7103cd722", "type": "concept", "title": "Representation, localization, cultural humility, testing with affected users, employee training, and complaint learning"}], "description": "Students design for varied bodies, senses, languages, identities, family structures, cultures, and digital abilities from the start."}]}, {"id": "e28e92ae-f1cd-4ebb-b7c6-bc44a8c40fcc", "type": "topic", "title": "Offer Design and Integrated Marketing Communications", "description": "Marketing brings an offer to market through a coordinated system of products, packages, messages, sales activity, media, and partnerships. Students learn to align communications with a real guest value proposition and operational capacity.", "children": [{"id": "e6c74ba0-9a3d-4f02-ba73-c17254267970", "type": "subtopic", "title": "Hospitality offer and portfolio design", "children": [{"id": "89a8ea8e-dcf5-4d95-8829-6e5bce6a17a1", "type": "concept", "title": "Rooms, tables, menus, amenities, activities, events, memberships, packages, add-ons, and ancillary services"}, {"id": "5a9cf2a4-d476-4a57-8015-b1a7cc09b4a5", "type": "concept", "title": "Product line, assortment, bundling, versioning, customization, seasonality, life cycle, and innovation pipeline"}, {"id": "856cc486-636a-4dbf-90eb-259848d3dec2", "type": "concept", "title": "Concept tests, minimum viable offer, operational feasibility, capacity, quality, safety, cost, and brand fit"}], "description": "Students assemble core, facilitating, supporting, and augmented services into bookable, deliverable, and profitable offers."}, {"id": "c2a77de9-3bce-420a-a36f-7624c1761ab2", "type": "subtopic", "title": "Message and creative strategy", "children": [{"id": "12c991ce-61a3-4164-88d3-e5f9413df297", "type": "concept", "title": "Communication objective, audience, barrier, promise, support, tone, call to action, and mandatories"}, {"id": "9584589d-2c75-4fa7-83ac-3dea79bb592c", "type": "concept", "title": "Awareness, comprehension, attitude, preference, intent, action, retention, advocacy, and hierarchy of effects"}, {"id": "cb53f045-7527-4e0b-a454-cf0839901d96", "type": "concept", "title": "Storytelling, imagery, social proof, scarcity, framing, emotional and rational appeals, pretesting, and adaptation"}], "description": "This subtopic turns a target insight and positioning into persuasive, distinctive, truthful creative work."}, {"id": "f15c273f-1bf1-4209-a197-45c10c00ff89", "type": "subtopic", "title": "Integrated communications and sales alignment", "children": [{"id": "8d1a0648-f5ed-4813-b3d3-5bdcbd28a73e", "type": "concept", "title": "Advertising, PR, sales promotion, direct marketing, email, events, partnerships, sponsorships, and trade marketing"}, {"id": "4893ba9f-e908-40a9-9450-cb9f6166d678", "type": "concept", "title": "Leisure, group, business travel, meetings, weddings, catering, corporate accounts, and destination sales"}, {"id": "670232cd-084a-49d5-ae0f-2bd759131928", "type": "concept", "title": "Campaign architecture, channel roles, frequency, sequencing, calendar, sales enablement, lead handoff, and message consistency"}], "description": "Students coordinate paid, owned, earned, shared, partner, public-relations, direct, experiential, and personal-selling activity."}]}, {"id": "32a5dc29-923d-4417-9cc3-24b872c11cf3", "type": "topic", "title": "Digital Marketing, Content, Search, Social, and Influencers", "description": "Digital discovery and persuasion now span search, maps, websites, apps, social platforms, creators, video, email, and emerging interfaces. Students learn channel craft while retaining strategic control of audience, message, measurement, and risk.", "children": [{"id": "bdac3076-f516-4dc7-8578-c72976147393", "type": "subtopic", "title": "Digital ecosystem and owned experience", "children": [{"id": "e9540d0f-9cad-44c5-9012-493d41acafe4", "type": "concept", "title": "Information architecture, mobile-first design, speed, accessibility, trust, localization, merchandising, and conversion paths"}, {"id": "7ad43668-f3d5-4027-b3be-8a759c51fd83", "type": "concept", "title": "Landing pages, booking flows, calls to action, forms, abandoned booking, remarketing, and testing"}, {"id": "1952402f-561d-4117-ac76-07301557c157", "type": "concept", "title": "Content governance, taxonomy, metadata, structured data, asset management, permissions, and freshness"}], "description": "Students evaluate how websites, booking engines, menus, maps, apps, email, messaging, and local listings move guests from intent to action."}, {"id": "e0a5eab5-2c0a-4593-9322-a36f90d6c884", "type": "subtopic", "title": "Search, content, social, and media", "children": [{"id": "8e89835b-d1bc-457e-959b-642ec88daf0c", "type": "concept", "title": "SEO, local search, paid search, metasearch, display, programmatic, video, OTT, and retail/travel media"}, {"id": "28c4732c-84d0-456e-86d0-e735c8ae8711", "type": "concept", "title": "Content pillars, search intent, editorial calendar, short-form video, user-generated content, and community management"}, {"id": "bc240d9b-d301-408e-b5fc-cbdb62748a3d", "type": "concept", "title": "Reach, frequency, attention, engagement, click-through, cost, quality, brand lift, key events, and incrementality"}], "description": "This subtopic integrates organic discovery, paid media, editorial usefulness, community participation, and creative platform fit."}, {"id": "c3fa96e9-aea4-46cc-ac2b-fb9bbe5bfe32", "type": "subtopic", "title": "Influencers, affiliates, and creator governance", "children": [{"id": "bbbcc68e-c10c-4dd0-a873-9a7411659160", "type": "concept", "title": "Creator fit, audience overlap, brief, deliverables, approval, disclosure, compensation, affiliate links, and exclusivity"}, {"id": "e51967a8-236b-40e5-a745-84eb3dd20c9a", "type": "concept", "title": "Rights, licensing, whitelisting, reuse, data access, cancellation, morality clauses, and crisis response"}, {"id": "05091798-bfd5-4547-b3ce-9bafff83ea04", "type": "concept", "title": "FTC material-connection disclosure, truthful claims, authentic experience, monitoring, fraud signals, and outcome evaluation"}], "description": "Students plan authentic collaborations while managing disclosure, brand safety, usage rights, measurement, and fake engagement."}]}, {"id": "761eff3c-802c-446c-8aea-6eb69f5ca164", "type": "topic", "title": "Distribution, E-Commerce, and Channel Economics", "description": "Distribution determines where hospitality inventory is displayed, compared, booked, paid for, modified, and serviced. Students connect marketing reach and convenience to commissions, data access, parity, control, and lifetime guest value.", "children": [{"id": "2dc01842-c31c-4e89-b2fc-05de9f0d2339", "type": "subtopic", "title": "Hospitality distribution landscape", "children": [{"id": "43890243-b8d8-431d-a7a7-05e4dbaf5e9b", "type": "concept", "title": "Brand.com, property direct, voice, app, GDS, OTA, metasearch, wholesaler, tour operator, TMC, and consortia"}, {"id": "e2e8a41d-7c50-4aed-8855-0c961c96f5f7", "type": "concept", "title": "CRS, PMS, booking engine, channel manager, rate shopping, content, availability, restrictions, and confirmation flow"}, {"id": "7166ed63-a365-4b1e-b001-a7d95d64965d", "type": "concept", "title": "Merchant, agency, opaque, package, allotment, free-sale, net-rate, commission, and transaction models"}], "description": "Students map direct and indirect routes from supplier inventory to leisure, corporate, group, and wholesale demand."}, {"id": "350906a0-c3d7-4726-b16e-e23d9e612b2b", "type": "subtopic", "title": "Channel strategy and merchandising", "children": [{"id": "35bef69c-0523-4c9a-9702-b725110533f2", "type": "concept", "title": "Reach, conversion, placement, content quality, reviews, offers, loyalty/member rates, packages, and mobile deals"}, {"id": "259f2a95-a170-480d-974c-3cf9a73a6fbc", "type": "concept", "title": "Rate parity, availability parity, closed-user groups, fences, attribution, leakage, conflict, and partner scorecards"}, {"id": "e8de5d04-9526-476f-bf29-8c1da0de8e53", "type": "concept", "title": "Need dates, compression, shoulder periods, dayparts, geographic/source markets, and campaign-channel fit"}], "description": "This subtopic uses segment, market, need period, funnel role, and capacity to decide where and how to sell."}, {"id": "11436688-a84e-4681-a902-3ce00440c570", "type": "subtopic", "title": "Channel economics and direct-booking value", "children": [{"id": "b8b79b2b-fffb-4ecd-b212-23486b378d85", "type": "concept", "title": "Commission, merchant discount, media cost, loyalty cost, cancellation, payment risk, service cost, and incremental labor"}, {"id": "e56a1f33-9cae-4010-adf8-9b5a77348844", "type": "concept", "title": "Customer acquisition cost, contribution per booking, net RevPAR/revenue, repeat direct behavior, and lifetime value"}, {"id": "e560ce6e-da82-45f1-8f52-3cd8ba8c7300", "type": "concept", "title": "Incrementality, displacement, cannibalization, assisted conversion, data ownership, and negotiation leverage"}], "description": "Students calculate net contribution rather than judging channels only by gross revenue or commission percentage."}]}, {"id": "f49bb5b0-7992-46f7-9fec-a73fb07c5472", "type": "topic", "title": "CRM, Loyalty, Personalization, and Relationship Economics", "description": "Relationship marketing seeks relevant, permissioned value over time. Students learn to design loyalty and CRM systems that improve the guest experience and business economics without treating data collection as a substitute for trust.", "children": [{"id": "6b44544d-1f39-4dde-a43a-7fd8c0d01118", "type": "subtopic", "title": "CRM architecture and lifecycle management", "children": [{"id": "760253ad-701a-45bb-9f06-a8a44df44130", "type": "concept", "title": "Profiles, identity resolution, reservation/POS/PMS interactions, preferences, cases, campaigns, and suppression rules"}, {"id": "539aac9d-17b8-42fd-a97a-5e9bc761e87a", "type": "concept", "title": "Acquisition, onboarding, pre-arrival, in-stay/visit, post-stay, reactivation, retention, churn, and win-back"}, {"id": "804e87dd-ceec-4e4a-97f2-e0977e3e8eec", "type": "concept", "title": "Segments, triggers, journeys, next-best action, contact policy, frequency caps, service recovery, and sales follow-up"}], "description": "Students organize first-party data, consent, identity, preferences, interactions, and service history around actionable guest relationships."}, {"id": "31d4f4f2-e650-4418-935a-106c0a17047c", "type": "subtopic", "title": "Loyalty-program design", "children": [{"id": "0d3bf19a-6004-409c-9f49-c3815b958e94", "type": "concept", "title": "Points, tiers, benefits, earn/burn, redemption, breakage, liability, partners, and elite recognition"}, {"id": "2f4073b6-8a2a-40c0-b909-781363cab0c4", "type": "concept", "title": "Member rates, experiences, upgrades, access, surprise and delight, gamification, coalition, and paid membership"}, {"id": "9dda798e-c137-4a1f-96e4-1a149bb288bf", "type": "concept", "title": "Enrollment, activation, engagement, retention, incremental spend, direct shift, redemption, cost, and fairness"}], "description": "This subtopic compares recognition, convenience, access, status, community, and economic rewards across different hospitality models."}, {"id": "afbcb6b5-5443-4d53-8069-f4f12a244dc8", "type": "subtopic", "title": "Personalization and lifetime value", "children": [{"id": "ea59aff4-b5d6-4a65-a570-df44e740d472", "type": "concept", "title": "Rules-based, predictive, contextual, human-led, real-time, and generative personalization"}, {"id": "b33ab2fe-c94d-4867-91e5-8533c8b27534", "type": "concept", "title": "Recency, frequency, monetary value, cohort retention, churn probability, contribution, CAC, and CLV"}, {"id": "49739436-b9c2-475b-ba7a-50233254c672", "type": "concept", "title": "Holdouts, incremental lift, privacy, sensitive attributes, proxy discrimination, creepiness, transparency, and guest control"}], "description": "Students distinguish helpful relevance from intrusive targeting and link relationship choices to future contribution."}]}, {"id": "8e51c788-35e0-4352-8b8a-2898e997544f", "type": "topic", "title": "Pricing, Promotions, and Commercial Strategy", "description": "Marketing, sales, distribution, and revenue management jointly shape profitable demand. Students evaluate price and promotions as signals, exchange terms, and capacity-allocation tools—not simply discounts.", "children": [{"id": "f53631bf-a9f1-4921-903c-fe6006ea4bf2", "type": "subtopic", "title": "Pricing foundations and guest perception", "children": [{"id": "753132b4-a56f-4c87-812f-047d9cb2e3fb", "type": "concept", "title": "Cost-plus, competitive, value-based, dynamic, package, subscription, membership, and auction approaches"}, {"id": "2b9b9889-81fa-4b20-aad5-7a5b8ff165ad", "type": "concept", "title": "Willingness to pay, elasticity, rate fences, versioning, anchoring, framing, decoys, and price-quality inference"}, {"id": "6a8f7cb2-2971-41e5-8cfc-677bba1f6310", "type": "concept", "title": "Fees, taxes, service charges, resort/destination fees, transparency, drip pricing risk, accessibility, and fairness"}], "description": "Students integrate cost, competition, demand, value, elasticity, reference prices, fairness, and brand position."}, {"id": "3070e729-5768-4af5-b662-62f1246fbd0b", "type": "subtopic", "title": "Promotion design and evaluation", "children": [{"id": "b43f1a56-951a-477f-9f12-6b45e2719800", "type": "concept", "title": "Discounts, packages, value-adds, coupons, codes, flash sales, gift cards, contests, and loyalty offers"}, {"id": "43fcd366-1b63-48da-9417-a73a05d7a1f4", "type": "concept", "title": "Objective, eligibility, fence, timing, inventory, blackout, terms, channel, redemption, fulfillment, and control"}, {"id": "8adc833f-9c85-400e-8086-81f3cdc4f936", "type": "concept", "title": "Incremental demand, contribution, displacement, cannibalization, pull-forward, repeat behavior, abuse, and post-promotion analysis"}], "description": "This subtopic separates a compelling tactical offer from permanent margin leakage or brand dilution."}, {"id": "4eb7edba-81ac-43d7-b58c-1a8b416ff00d", "type": "subtopic", "title": "Commercial integration", "children": [{"id": "b4b9c487-c6fc-4353-9bd2-49cac2402464", "type": "concept", "title": "Demand calendar, forecast, pace, pickup, need periods, segment/channel mix, group pipeline, and capacity"}, {"id": "e2ce1638-0262-417a-a210-1f48e027b640", "type": "concept", "title": "Campaign-response assumptions, lead time, conversion, cancellation, no-show, length of stay, ancillary spend, and flow-through"}, {"id": "36890810-ae5a-4baa-964e-540df49c929a", "type": "concept", "title": "Commercial meetings, shared metrics, decision rights, test-and-learn backlog, tradeoffs, and forecast feedback"}], "description": "Students align marketing demand generation with revenue decisions, sales pipelines, inventory, operations, and profit goals."}]}, {"id": "6be0cf96-ac8b-4672-afba-9f3f0e257323", "type": "topic", "title": "Reputation, Reviews, Service Recovery, and Crisis Communication", "description": "Hospitality reputation is produced by real experiences and amplified by platforms, media, and word of mouth. Students learn to listen, respond, recover, and improve without manipulating the evidence guests depend on.", "children": [{"id": "9a382833-871d-497d-a337-07ddf64cd115", "type": "subtopic", "title": "Review and reputation intelligence", "children": [{"id": "7f8035b8-79d0-41db-ba7d-a044b856086b", "type": "concept", "title": "Review sources, verified stays, sampling, recency, volume, score distribution, sentiment, topics, and language"}, {"id": "d6fc0766-184d-4ee1-9f7d-c12cd3d53f18", "type": "concept", "title": "Operational root causes, expectations, property/outlet/segment differences, trends, alerts, and closed-loop ownership"}, {"id": "b715f6db-a5a1-44db-8ab0-04263c81b614", "type": "concept", "title": "Benchmark comparability, platform rules, fake-review signals, incentives, moderation, and evidentiary limits"}], "description": "Students analyze rating distributions, volume, recency, text, themes, response patterns, and competitor context."}, {"id": "6a12c8eb-1076-4952-8da3-e1a8e1f92a97", "type": "subtopic", "title": "Response and service recovery", "children": [{"id": "087f427d-8dcb-4b65-929f-9e7fbbb4e497", "type": "concept", "title": "Listen, acknowledge, apologize where appropriate, explain without defensiveness, resolve, follow up, and document"}, {"id": "a600a62a-baa8-42c6-80b2-d824a7c8f9a2", "type": "concept", "title": "Public versus private response, personal data, safety, discrimination, threats, charge disputes, legal escalation, and employee support"}, {"id": "5b1eb0c8-daac-4b9f-bf63-083833dab77d", "type": "concept", "title": "Recovery authority, compensation guardrails, case routing, root-cause coding, learning review, and prevention"}], "description": "This subtopic develops timely, human, privacy-aware responses that acknowledge experience, solve what can be solved, and feed operational learning."}, {"id": "656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f", "type": "subtopic", "title": "Crisis and issues communication", "children": [{"id": "4e2afcd2-01a3-446f-8a15-684eaeb30a2c", "type": "concept", "title": "Crisis team, stakeholder map, holding statement, facts, approvals, spokesperson, channels, accessibility, and cadence"}, {"id": "7029ed7c-7efa-497c-8482-89afdccc25fc", "type": "concept", "title": "Safety, weather, cyber events, health, labor, discrimination, influencer incidents, operational disruption, and misinformation"}, {"id": "d566eed4-bcf8-464c-ac35-8d4360199ccc", "type": "concept", "title": "Speed versus certainty, empathy, rumor control, media monitoring, correction, recovery narrative, and after-action review"}], "description": "Students prepare for sudden events that affect safety, trust, access, operations, employees, destinations, or brand meaning."}]}, {"id": "0d0d1de8-bb81-460b-b0f4-11c27afccb24", "type": "topic", "title": "Marketing Analytics, Experimentation, Attribution, and ROI", "description": "Measurement should improve decisions, not merely decorate reports. Students build a metric system from business objective to guest behavior, financial outcome, causal evidence, and action.", "children": [{"id": "0b5272f9-ee28-4a49-9bde-58fb582dafca", "type": "subtopic", "title": "Measurement architecture and funnel", "children": [{"id": "14b25a3a-f8b3-4b8d-9eb6-fa6ef29771e7", "type": "concept", "title": "Objective, KPI, diagnostic metric, dimension, event, source, owner, target, threshold, and decision rule"}, {"id": "21b7ce08-ca54-4abf-96cf-08ecbd1b2183", "type": "concept", "title": "Reach, frequency, engagement, sessions, qualified traffic, leads, booking starts, conversion, revenue, cancellation, and retention"}, {"id": "0109e82c-3a6e-4f71-ba29-54d53149b520", "type": "concept", "title": "Metric dictionary, UTM taxonomy, campaign naming, tag plan, data layer, QA, reconciliation, latency, and versioning"}], "description": "Students define observable events and consistent metrics across awareness, consideration, booking, experience, retention, and advocacy."}, {"id": "3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d", "type": "subtopic", "title": "Economics and performance analysis", "children": [{"id": "13fe4148-cb8d-42bd-8978-7dc916112cc9", "type": "concept", "title": "CPM, CPC, cost per lead, cost per acquisition, ROAS, marketing ROI, contribution, payback, and lifetime value"}, {"id": "feec25ae-7b86-4874-a3b2-16327a9cbfc7", "type": "concept", "title": "Budget, marginal return, saturation, diminishing returns, portfolio allocation, scenario, sensitivity, and opportunity cost"}, {"id": "b1d8d5ee-ae64-4dd5-bfbc-80a640b9b44f", "type": "concept", "title": "Segment, channel, market, creative, device, cohort, property, outlet, and period analysis"}], "description": "This subtopic connects media and campaign performance to contribution rather than stopping at impressions, clicks, or gross revenue."}, {"id": "6d6ef760-be6d-477a-887e-88b54205b15f", "type": "subtopic", "title": "Experiments, attribution, and incrementality", "children": [{"id": "80fca97e-c271-4fa1-b1ba-ffa09b8f0728", "type": "concept", "title": "A/B and multivariate tests, randomized holdouts, geo tests, pre/post, matched markets, sample size, power, and guardrails"}, {"id": "40921dc7-2f6e-41b5-affc-6e7b47bde1d5", "type": "concept", "title": "Last-click, rules-based, data-driven, multi-touch, view-through, modeled events, lookback windows, and walled gardens"}, {"id": "bf8c85b1-6cab-4357-aa7d-fae14bc884cb", "type": "concept", "title": "Incremental lift, selection bias, spillover, novelty, seasonality, statistical versus managerial significance, and replication"}], "description": "Students distinguish correlation from causation and interpret platform attribution with appropriate skepticism."}]}, {"id": "b43403db-4520-44c1-b9bd-f93816e90764", "type": "topic", "title": "Ethics, Privacy, Responsible AI, Sustainability, and Trust", "description": "Marketing power carries duties to guests, employees, communities, partners, and the brand. Students evaluate whether a tactic is lawful, truthful, inclusive, secure, environmentally credible, and worthy of trust—not merely whether it performs.", "children": [{"id": "b655baa9-cc8d-419b-9eae-41da4adff42c", "type": "subtopic", "title": "Truthful and fair marketing", "children": [{"id": "ffbf0e37-16c3-4714-9710-19893e03c362", "type": "concept", "title": "Claim substantiation, clear and conspicuous disclosures, material connections, native ads, endorsements, and testimonials"}, {"id": "949c56b7-ac69-45e4-b4cf-4e267c3f0241", "type": "concept", "title": "FTC Consumer Review Rule, fake or AI-generated reviews, review suppression, incentives, insider reviews, and threats"}, {"id": "a19a7114-63cc-4843-affc-ff3501952991", "type": "concept", "title": "Dark patterns, false urgency, misleading availability, hidden conditions, drip pricing, vulnerable audiences, and documentation"}], "description": "Students apply U.S. truth-in-advertising principles to claims, endorsements, reviews, prices, promotions, scarcity, and targeting."}, {"id": "b6686f28-9d9d-423d-9ab2-875883e90fb4", "type": "subtopic", "title": "Privacy, security, and data governance", "children": [{"id": "17934b43-abd2-47b5-8486-69ffe8b44ec9", "type": "concept", "title": "First-, second-, and third-party data; consent; notice; preference; deletion; access; portability; and opt-out concepts"}, {"id": "ed8e1b05-09d3-4282-8375-02703a8509ef", "type": "concept", "title": "Sensitive data, location, children, biometrics, accessibility needs, payment, identity, loyalty, and employee information"}, {"id": "c98b3642-86fc-4ca5-a0ff-e49908cae6cb", "type": "concept", "title": "Data inventory, lawful purpose, minimization, retention, role-based access, vendor contracts, breach response, and state-law review"}], "description": "This subtopic teaches data minimization, purpose limitation, access control, retention, and vendor oversight in a changing legal environment."}, {"id": "cc8e6573-3b8a-4556-8df8-6984a8faf1e0", "type": "subtopic", "title": "Responsible AI and credible sustainability", "children": [{"id": "df8a1f1a-2f58-4c18-b959-7ce34c5ce9c4", "type": "concept", "title": "Generative content, translation, personalization, recommendations, forecasting, social listening, synthetic media, and agents"}, {"id": "2230deda-01c1-4174-8659-5698ab03949d", "type": "concept", "title": "Accuracy, hallucination, bias, representational harm, intellectual property, disclosure, prompt/data leakage, monitoring, and human approval"}, {"id": "7cfe818c-ff79-4cfd-83d2-997c2cfc53d4", "type": "concept", "title": "Environmental and social claims, boundaries, baselines, materiality, substantiation, greenwashing, community impact, and accessible benefits"}], "description": "Students use AI and sustainability claims with accountable human judgment, evidence, testing, and transparency."}]}, {"id": "598d1376-2f54-43b2-a081-b3b021f5a388", "type": "topic", "title": "Integrated Hospitality Marketing Plan and Campaign Execution", "description": "The capstone integrates analysis, choice, creative strategy, channels, operations, economics, governance, measurement, and learning. The plan is a decision system with owners and contingencies—not a slide deck of disconnected tactics.", "children": [{"id": "11cd3cda-038c-4b5f-b5f9-4a7a8aaf44e0", "type": "subtopic", "title": "Situation, objectives, and strategy", "children": [{"id": "e5ea14cd-647c-4301-9c1e-84de92562e14", "type": "concept", "title": "Business context, performance baseline, research insight, market opportunity, problem statement, and assumptions"}, {"id": "38a1cc51-4874-4118-b306-557ea5e6663e", "type": "concept", "title": "SMART objectives, target segments, positioning, value proposition, offer, competitive response, and strategic choices"}, {"id": "94431bcc-48e0-412c-bfdf-f65cde3e5081", "type": "concept", "title": "SWOT used as synthesis, risks, constraints, dependencies, stakeholder impacts, and success conditions"}], "description": "Students synthesize internal, customer, competitor, channel, and environmental evidence into a focused strategic diagnosis."}, {"id": "e6abc448-00bb-4fa9-87c8-4ea5eeac0eb6", "type": "subtopic", "title": "Tactics, resources, and implementation", "children": [{"id": "7cff85a9-9c61-4328-ad04-2d88d8972b06", "type": "concept", "title": "Journey, message hierarchy, creative idea, content, media, PR, sales, distribution, CRM, loyalty, and partnerships"}, {"id": "c3abf166-e68c-4c0b-8b2f-569a1a2d66be", "type": "concept", "title": "Budget, calendar, work breakdown, owners, approvals, assets, technology, vendors, training, capacity, and service readiness"}, {"id": "21a6cdce-05b1-4500-87fd-64b2b2925b20", "type": "concept", "title": "RACI, governance, brand/legal/privacy review, accessibility QA, launch checklist, escalation, and contingency plan"}], "description": "This subtopic translates strategy into a coordinated campaign and operating plan that can actually be delivered."}, {"id": "2637cd0d-3d4a-449e-a976-5f169f0e7fe0", "type": "subtopic", "title": "Measurement, optimization, and defense", "children": [{"id": "409a7b40-d79c-4412-92f4-9419d655fcb8", "type": "concept", "title": "KPI tree, targets, dashboard, data sources, attribution, experiments, holdouts, forecast, and financial case"}, {"id": "48c2e214-5e1d-4772-a97f-cbef8db92959", "type": "concept", "title": "Review cadence, alerts, optimization rules, learning agenda, budget shifts, stop/scale criteria, and post-campaign review"}, {"id": "e9e8142a-049a-4cf7-9bbb-d96ce75a4e45", "type": "concept", "title": "Executive summary, oral defense, limitations, alternative strategies, stakeholder questions, and implementation recommendation"}], "description": "Students specify how evidence will change decisions and defend their plan against commercial, operational, ethical, and analytical challenges."}]}], "dbBacked": true}$hmktjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'hospitality-marketing'
);

update public.learning_paths
set
  title = 'Hospitality Marketing',
  goal = 'Hospitality Marketing',
  summary = 'This course prepares students to analyze, design, execute, measure, and improve marketing for hotels, resorts, restaurants, clubs, events, attractions, and related service organizations. Students use consumer research and market intelligence to select targets, position brands, design offers and guest journeys, coordinate integrated communications, manage digital and distribution channels, build CRM and loyalty programs, evaluate pricing and promotions, protect reputation, and allocate resources using experiments and financial evidence. U.S. truth-in-advertising, review, privacy, accessibility, and AI governance issues are embedded throughout, with global and cultural contexts considered where relevant.',
  data = $hmktjson${"slug": "hospitality-marketing", "title": "Hospitality Marketing", "description": "This course prepares students to analyze, design, execute, measure, and improve marketing for hotels, resorts, restaurants, clubs, events, attractions, and related service organizations. Students use consumer research and market intelligence to select targets, position brands, design offers and guest journeys, coordinate integrated communications, manage digital and distribution channels, build CRM and loyalty programs, evaluate pricing and promotions, protect reputation, and allocate resources using experiments and financial evidence. U.S. truth-in-advertising, review, privacy, accessibility, and AI governance issues are embedded throughout, with global and cultural contexts considered where relevant.", "topics": [{"id": "b7b1856c-b6f6-441b-af29-5042d2f550e3", "type": "topic", "title": "Hospitality Marketing, Service Logic, and Strategic Value", "description": "Hospitality marketing creates and communicates value before, during, and after a guest experience. This section frames marketing as an enterprise discipline that connects guest needs, operations, revenue, brand promises, and long-term relationships.", "children": [{"id": "1e39d3f3-1529-4471-8bcf-12935d4672dd", "type": "subtopic", "title": "Services-marketing fundamentals", "children": [{"id": "3b4dfac1-415c-488f-8d49-d7fb6aa60e81", "type": "concept", "title": "Intangibility, inseparability, variability, perishability, ownership, and perceived risk"}, {"id": "300b4877-6474-434e-8ca0-9d6f30ea8641", "type": "concept", "title": "The expanded service mix: product, price, place, promotion, people, process, and physical evidence"}, {"id": "0b842042-4e79-4073-b88d-b809aa9b076a", "type": "concept", "title": "Expectation formation, moments of truth, service scripts, signaling, guarantees, and recovery"}], "description": "Students learn why intangible, variable, perishable, and co-produced experiences require different choices from packaged goods."}, {"id": "a3a34072-f8e9-4ace-b7c7-00795a3f1d56", "type": "subtopic", "title": "Market orientation and value creation", "children": [{"id": "fe34511f-b883-40f5-a63f-3418c9ceb18c", "type": "concept", "title": "Customer orientation, competitor orientation, cross-functional coordination, learning, and responsiveness"}, {"id": "c25b2c86-a1df-4390-ba5c-894338219478", "type": "concept", "title": "Customer value, benefits, sacrifices, jobs-to-be-done, differentiation, parity, and switching costs"}, {"id": "ebdc000b-6a26-4ad7-b01c-761fb85bbff6", "type": "concept", "title": "Mission, objectives, capabilities, constraints, stakeholder value, and marketing's role in profitable demand"}], "description": "This subtopic turns guest, competitor, and operational evidence into a coherent value proposition and strategic direction."}, {"id": "94da44da-efab-478d-9492-14ecf3251873", "type": "subtopic", "title": "Hospitality sectors and business models", "children": [{"id": "4768925b-e8d9-4c5a-99b4-5ad0d5befca1", "type": "concept", "title": "Hotels, resorts, restaurants, vacation rentals, clubs, casinos, cruises, venues, and destinations"}, {"id": "787c1520-03c1-44fb-aeaf-46b34353a35e", "type": "concept", "title": "Owned, managed, franchised, licensed, independent, platform, membership, and asset-light models"}, {"id": "239fd64c-5583-43ce-a3c9-37c60f2a2c2a", "type": "concept", "title": "Demand perishability, fixed capacity, seasonality, ancillary revenue, labor intensity, and network effects"}], "description": "Students compare how marketing economics change across lodging, foodservice, clubs, events, attractions, travel, and destinations."}]}, {"id": "108b2414-4178-4370-bb5b-ccf90920ab37", "type": "topic", "title": "Consumer Behavior, Research, and Market Intelligence", "description": "Strong hospitality marketing starts with disciplined curiosity about people, context, and demand. Students learn to replace assumptions with evidence while respecting research ethics and the limits of available data.", "children": [{"id": "11c715ec-ad2f-4750-ba22-7ee221ec2171", "type": "subtopic", "title": "Guest decision behavior", "children": [{"id": "9719617d-14d4-4749-8feb-89dab219148d", "type": "concept", "title": "Need recognition, information search, consideration sets, booking, consumption, evaluation, sharing, and repeat behavior"}, {"id": "d525f9cb-4019-41f0-8e94-fd78b91a8624", "type": "concept", "title": "Functional, emotional, social, sensory, experiential, and transformative benefits"}, {"id": "3d9808b3-20e6-4e20-a92c-beee19b6834f", "type": "concept", "title": "Reference groups, household roles, culture, identity, accessibility needs, travel party, occasion, and situational factors"}], "description": "Students examine how motivation, perception, memory, emotion, culture, social influence, and risk shape hospitality choice and evaluation."}, {"id": "d2f1d090-0c00-45d3-9e59-febc163cb713", "type": "subtopic", "title": "Marketing research design", "children": [{"id": "02c8ef66-2e92-4017-b6ca-cdb7960d1140", "type": "concept", "title": "Decision problem, research question, hypotheses, constructs, measures, sampling, and analysis plan"}, {"id": "49eba0c6-cab6-43cd-93c8-a1ec827abc58", "type": "concept", "title": "Exploratory, descriptive, causal, qualitative, quantitative, observational, survey, interview, focus group, and experiment methods"}, {"id": "1d7043a7-3647-4886-b9d1-7d2fb7f0e449", "type": "concept", "title": "Validity, reliability, bias, confounding, nonresponse, representativeness, triangulation, and ethical consent"}], "description": "This subtopic develops the ability to turn a managerial problem into an answerable research question and credible evidence plan."}, {"id": "c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db", "type": "subtopic", "title": "Market and competitor intelligence", "children": [{"id": "5b208697-c7ad-45b4-a432-587592053cf0", "type": "concept", "title": "Market size, growth, share, penetration, demand drivers, seasonality, source markets, and trip purpose"}, {"id": "967a7828-9358-48d2-af59-2c4e60566810", "type": "concept", "title": "Competitive sets, rate/product audits, review mining, social listening, search trends, and mystery shopping"}, {"id": "de45dc19-a114-4917-bd14-26f3012961ee", "type": "concept", "title": "PESTLE, five forces, scenario signals, source quality, freshness, comparability, and uncertainty"}], "description": "Students assemble demand, competitor, channel, trend, and internal evidence without confusing a benchmark with a strategy."}]}, {"id": "894704ee-4042-42a2-a1af-ea09c90d1c94", "type": "topic", "title": "Segmentation, Targeting, Positioning, and Personas", "description": "Segmentation concentrates resources on meaningfully different needs and behaviors. Students learn to select attractive targets and create a position that can be delivered consistently—not merely write colorful personas.", "children": [{"id": "ab636d9c-a303-41e8-95d6-c66f33751f02", "type": "subtopic", "title": "Segmentation design", "children": [{"id": "9098ff59-7d8c-4e98-bfbc-47a03500ad6f", "type": "concept", "title": "Geographic, demographic, psychographic, behavioral, occasion, benefit, needs-based, firmographic, and value segments"}, {"id": "bfebd93d-6add-4875-99fd-7d770f90bf73", "type": "concept", "title": "Individual traveler, household, group, corporate account, intermediary, event planner, member, and local resident units"}, {"id": "b519365b-6d89-4b8f-a180-2064846b0951", "type": "concept", "title": "Identifiability, substantiality, stability, accessibility, differentiability, actionability, privacy, and fairness"}], "description": "Students divide markets using variables that predict needs, choice, value, or response and that managers can actually reach and serve."}, {"id": "c13fd011-6e5a-4e5d-afae-5dae53f23eee", "type": "subtopic", "title": "Target-market selection", "children": [{"id": "8834b530-0881-432f-a940-73aec35dda93", "type": "concept", "title": "Market potential, growth, competition, price sensitivity, acquisition cost, retention, ancillary spend, and seasonality"}, {"id": "d931f311-4d7e-432c-aae5-b2a9d55d2c1c", "type": "concept", "title": "Undifferentiated, differentiated, concentrated, local, niche, account-based, and one-to-one strategies"}, {"id": "7adff2e8-37bd-413a-92ed-6abb968bdbea", "type": "concept", "title": "Primary, secondary, exclusion, priority, capacity allocation, cannibalization, and portfolio balance"}], "description": "This subtopic compares segment attractiveness with strategic fit, cost to serve, capacity, risk, and likely lifetime economics."}, {"id": "56f7a2fe-7d2a-4526-9065-b4efc5f10b85", "type": "subtopic", "title": "Positioning and evidence-based personas", "children": [{"id": "7399b8a4-95e5-42f8-b6df-4db6f98a878a", "type": "concept", "title": "Frame of reference, target, insight, benefit, points of difference, points of parity, proof, and brand essence"}, {"id": "4d0665a4-cbc1-4f59-8f1e-0fdca3b4ba62", "type": "concept", "title": "Perceptual maps, value curves, positioning statements, message hierarchy, and competitive response"}, {"id": "9b6b099f-9de0-4ec3-bb77-6169a840b3e7", "type": "concept", "title": "Persona goals, behaviors, barriers, context, evidence, uncertainty, anti-stereotyping, and update cadence"}], "description": "Students turn research into a differentiated promise, reasons to believe, and practical decision tools for teams."}]}, {"id": "d648e2ca-b80c-4f49-b9ea-28ebdf942862", "type": "topic", "title": "Brand Strategy, Architecture, and Experience Design", "description": "A hospitality brand is a memory structure and an operating promise. This section connects identity and communications to standards, spaces, people, technology, partnerships, and the economics of a brand portfolio.", "children": [{"id": "bcf956a0-29ab-4c70-9010-2be331fa8fb7", "type": "subtopic", "title": "Brand identity and equity", "children": [{"id": "71665230-8a6a-4fe3-8ede-2fbaf45b7f24", "type": "concept", "title": "Purpose, values, personality, voice, visual identity, symbols, sensory codes, story, and heritage"}, {"id": "afcb6a7f-c2d9-4394-91c1-063e84bc8872", "type": "concept", "title": "Salience, imagery, judgments, feelings, resonance, familiarity, distinctiveness, and mental availability"}, {"id": "528ff1ae-f674-43fc-a802-562b52766cea", "type": "concept", "title": "Brand tracking, preference, consideration, price premium, advocacy, reputation, and financial contribution"}], "description": "Students learn how awareness, associations, perceived quality, trust, meaning, and loyalty create preference and pricing power."}, {"id": "4cae028c-d45e-421f-b245-f4a655e8db8a", "type": "subtopic", "title": "Brand architecture and portfolios", "children": [{"id": "fef01e6e-3265-41eb-a3b6-07b3b4e392c6", "type": "concept", "title": "Branded house, house of brands, endorsed brands, soft brands, collections, and independent affiliation"}, {"id": "956b4397-e138-4fca-9b36-5229d1a8d8e0", "type": "concept", "title": "Segment coverage, overlap, cannibalization, extension, licensing, franchising, conversion, and brand standards"}, {"id": "209f137b-363e-4663-aab9-b3a07b53a6e8", "type": "concept", "title": "Owner, operator, brand, franchisee, destination, chef, venue, and co-brand governance"}], "description": "This subtopic clarifies relationships among corporate, master, endorsed, collection, sub-brand, property, outlet, and partner brands."}, {"id": "c213da86-9bd3-4c61-97aa-32d902376ad3", "type": "subtopic", "title": "Experience and physical-evidence design", "children": [{"id": "205f4e15-0f3a-4591-91f5-30f8b51ae0b4", "type": "concept", "title": "Servicescape, atmosphere, sensory design, signage, collateral, uniforms, interface, accessibility, and wayfinding"}, {"id": "2f17aa85-67fb-4444-930d-cd95d6520b08", "type": "concept", "title": "Brand standards, service rituals, scripts, personalization, local authenticity, employee enablement, and empowerment"}, {"id": "b8c2a201-57ba-4332-806f-e8c6a9f508b3", "type": "concept", "title": "Concept testing, prototyping, blueprinting, consistency, adaptation, maintenance, and experience measurement"}], "description": "Students translate positioning into the visible and invisible cues that make the promise credible at every touchpoint."}]}, {"id": "2d9aeef6-0613-4fc9-bd30-c2f79ec377b4", "type": "topic", "title": "Customer Journey, Service Quality, and Inclusive Experience", "description": "Journey management reveals how many teams and platforms shape one guest relationship. Students diagnose friction, design accessible experiences, and close the loop between promised and delivered service.", "children": [{"id": "70d1f169-2e31-4e06-99a4-762f050d5517", "type": "subtopic", "title": "Journey mapping and service blueprinting", "children": [{"id": "b923be61-a9f2-438d-86a2-b0b48975b539", "type": "concept", "title": "Dreaming, planning, search, booking, pre-arrival, arrival, stay/visit, departure, post-stay, and return"}, {"id": "963f434b-856b-410e-8445-40e1a78914eb", "type": "concept", "title": "Touchpoints, moments of truth, pain points, delight, effort, wait, uncertainty, handoffs, and channel switching"}, {"id": "2a6781e0-274a-49ed-b36b-1eb901e29d49", "type": "concept", "title": "Frontstage, backstage, support process, data flow, ownership, service standards, and recovery triggers"}], "description": "Students map guest goals, actions, emotions, channels, handoffs, backstage processes, systems, and failure points."}, {"id": "fae7bdfe-0261-4eff-b31d-5c4685f4a677", "type": "subtopic", "title": "Service quality and experience measurement", "children": [{"id": "1aa02b63-b02d-47af-ad18-ca4b1a916d3d", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, tangibles, outcome quality, process quality, and value"}, {"id": "f33dd84c-fc15-4e70-8631-5780344ba8a5", "type": "concept", "title": "Satisfaction, overall rating, recommendation, effort, sentiment, complaints, repeat intent, and observed behavior"}, {"id": "088ae46a-6169-49db-8954-1c984d9af5ff", "type": "concept", "title": "Expectation effects, survey timing, scale design, response bias, benchmarks, drivers, and qualitative context"}], "description": "This subtopic combines perception and operational evidence to understand whether the experience met relevant expectations."}, {"id": "5a72cb61-340d-43c4-929c-1fa41ddcd8f1", "type": "subtopic", "title": "Accessibility, inclusion, and cultural intelligence", "children": [{"id": "19aafbfa-5923-4d16-a3f9-a4d5cf7ae9ff", "type": "concept", "title": "Universal design, accessible websites/content, captions, alt text, contrast, readable language, and assistive technology"}, {"id": "954b1d6c-c4df-4dea-9273-7251d5643af8", "type": "concept", "title": "Mobility, sensory, cognitive, dietary, allergy, religious, family, gender, language, and financial considerations"}, {"id": "ddf405c6-179c-4e54-ba64-16f7103cd722", "type": "concept", "title": "Representation, localization, cultural humility, testing with affected users, employee training, and complaint learning"}], "description": "Students design for varied bodies, senses, languages, identities, family structures, cultures, and digital abilities from the start."}]}, {"id": "e28e92ae-f1cd-4ebb-b7c6-bc44a8c40fcc", "type": "topic", "title": "Offer Design and Integrated Marketing Communications", "description": "Marketing brings an offer to market through a coordinated system of products, packages, messages, sales activity, media, and partnerships. Students learn to align communications with a real guest value proposition and operational capacity.", "children": [{"id": "e6c74ba0-9a3d-4f02-ba73-c17254267970", "type": "subtopic", "title": "Hospitality offer and portfolio design", "children": [{"id": "89a8ea8e-dcf5-4d95-8829-6e5bce6a17a1", "type": "concept", "title": "Rooms, tables, menus, amenities, activities, events, memberships, packages, add-ons, and ancillary services"}, {"id": "5a9cf2a4-d476-4a57-8015-b1a7cc09b4a5", "type": "concept", "title": "Product line, assortment, bundling, versioning, customization, seasonality, life cycle, and innovation pipeline"}, {"id": "856cc486-636a-4dbf-90eb-259848d3dec2", "type": "concept", "title": "Concept tests, minimum viable offer, operational feasibility, capacity, quality, safety, cost, and brand fit"}], "description": "Students assemble core, facilitating, supporting, and augmented services into bookable, deliverable, and profitable offers."}, {"id": "c2a77de9-3bce-420a-a36f-7624c1761ab2", "type": "subtopic", "title": "Message and creative strategy", "children": [{"id": "12c991ce-61a3-4164-88d3-e5f9413df297", "type": "concept", "title": "Communication objective, audience, barrier, promise, support, tone, call to action, and mandatories"}, {"id": "9584589d-2c75-4fa7-83ac-3dea79bb592c", "type": "concept", "title": "Awareness, comprehension, attitude, preference, intent, action, retention, advocacy, and hierarchy of effects"}, {"id": "cb53f045-7527-4e0b-a454-cf0839901d96", "type": "concept", "title": "Storytelling, imagery, social proof, scarcity, framing, emotional and rational appeals, pretesting, and adaptation"}], "description": "This subtopic turns a target insight and positioning into persuasive, distinctive, truthful creative work."}, {"id": "f15c273f-1bf1-4209-a197-45c10c00ff89", "type": "subtopic", "title": "Integrated communications and sales alignment", "children": [{"id": "8d1a0648-f5ed-4813-b3d3-5bdcbd28a73e", "type": "concept", "title": "Advertising, PR, sales promotion, direct marketing, email, events, partnerships, sponsorships, and trade marketing"}, {"id": "4893ba9f-e908-40a9-9450-cb9f6166d678", "type": "concept", "title": "Leisure, group, business travel, meetings, weddings, catering, corporate accounts, and destination sales"}, {"id": "670232cd-084a-49d5-ae0f-2bd759131928", "type": "concept", "title": "Campaign architecture, channel roles, frequency, sequencing, calendar, sales enablement, lead handoff, and message consistency"}], "description": "Students coordinate paid, owned, earned, shared, partner, public-relations, direct, experiential, and personal-selling activity."}]}, {"id": "32a5dc29-923d-4417-9cc3-24b872c11cf3", "type": "topic", "title": "Digital Marketing, Content, Search, Social, and Influencers", "description": "Digital discovery and persuasion now span search, maps, websites, apps, social platforms, creators, video, email, and emerging interfaces. Students learn channel craft while retaining strategic control of audience, message, measurement, and risk.", "children": [{"id": "bdac3076-f516-4dc7-8578-c72976147393", "type": "subtopic", "title": "Digital ecosystem and owned experience", "children": [{"id": "e9540d0f-9cad-44c5-9012-493d41acafe4", "type": "concept", "title": "Information architecture, mobile-first design, speed, accessibility, trust, localization, merchandising, and conversion paths"}, {"id": "7ad43668-f3d5-4027-b3be-8a759c51fd83", "type": "concept", "title": "Landing pages, booking flows, calls to action, forms, abandoned booking, remarketing, and testing"}, {"id": "1952402f-561d-4117-ac76-07301557c157", "type": "concept", "title": "Content governance, taxonomy, metadata, structured data, asset management, permissions, and freshness"}], "description": "Students evaluate how websites, booking engines, menus, maps, apps, email, messaging, and local listings move guests from intent to action."}, {"id": "e0a5eab5-2c0a-4593-9322-a36f90d6c884", "type": "subtopic", "title": "Search, content, social, and media", "children": [{"id": "8e89835b-d1bc-457e-959b-642ec88daf0c", "type": "concept", "title": "SEO, local search, paid search, metasearch, display, programmatic, video, OTT, and retail/travel media"}, {"id": "28c4732c-84d0-456e-86d0-e735c8ae8711", "type": "concept", "title": "Content pillars, search intent, editorial calendar, short-form video, user-generated content, and community management"}, {"id": "bc240d9b-d301-408e-b5fc-cbdb62748a3d", "type": "concept", "title": "Reach, frequency, attention, engagement, click-through, cost, quality, brand lift, key events, and incrementality"}], "description": "This subtopic integrates organic discovery, paid media, editorial usefulness, community participation, and creative platform fit."}, {"id": "c3fa96e9-aea4-46cc-ac2b-fb9bbe5bfe32", "type": "subtopic", "title": "Influencers, affiliates, and creator governance", "children": [{"id": "bbbcc68e-c10c-4dd0-a873-9a7411659160", "type": "concept", "title": "Creator fit, audience overlap, brief, deliverables, approval, disclosure, compensation, affiliate links, and exclusivity"}, {"id": "e51967a8-236b-40e5-a745-84eb3dd20c9a", "type": "concept", "title": "Rights, licensing, whitelisting, reuse, data access, cancellation, morality clauses, and crisis response"}, {"id": "05091798-bfd5-4547-b3ce-9bafff83ea04", "type": "concept", "title": "FTC material-connection disclosure, truthful claims, authentic experience, monitoring, fraud signals, and outcome evaluation"}], "description": "Students plan authentic collaborations while managing disclosure, brand safety, usage rights, measurement, and fake engagement."}]}, {"id": "761eff3c-802c-446c-8aea-6eb69f5ca164", "type": "topic", "title": "Distribution, E-Commerce, and Channel Economics", "description": "Distribution determines where hospitality inventory is displayed, compared, booked, paid for, modified, and serviced. Students connect marketing reach and convenience to commissions, data access, parity, control, and lifetime guest value.", "children": [{"id": "2dc01842-c31c-4e89-b2fc-05de9f0d2339", "type": "subtopic", "title": "Hospitality distribution landscape", "children": [{"id": "43890243-b8d8-431d-a7a7-05e4dbaf5e9b", "type": "concept", "title": "Brand.com, property direct, voice, app, GDS, OTA, metasearch, wholesaler, tour operator, TMC, and consortia"}, {"id": "e2e8a41d-7c50-4aed-8855-0c961c96f5f7", "type": "concept", "title": "CRS, PMS, booking engine, channel manager, rate shopping, content, availability, restrictions, and confirmation flow"}, {"id": "7166ed63-a365-4b1e-b001-a7d95d64965d", "type": "concept", "title": "Merchant, agency, opaque, package, allotment, free-sale, net-rate, commission, and transaction models"}], "description": "Students map direct and indirect routes from supplier inventory to leisure, corporate, group, and wholesale demand."}, {"id": "350906a0-c3d7-4726-b16e-e23d9e612b2b", "type": "subtopic", "title": "Channel strategy and merchandising", "children": [{"id": "35bef69c-0523-4c9a-9702-b725110533f2", "type": "concept", "title": "Reach, conversion, placement, content quality, reviews, offers, loyalty/member rates, packages, and mobile deals"}, {"id": "259f2a95-a170-480d-974c-3cf9a73a6fbc", "type": "concept", "title": "Rate parity, availability parity, closed-user groups, fences, attribution, leakage, conflict, and partner scorecards"}, {"id": "e8de5d04-9526-476f-bf29-8c1da0de8e53", "type": "concept", "title": "Need dates, compression, shoulder periods, dayparts, geographic/source markets, and campaign-channel fit"}], "description": "This subtopic uses segment, market, need period, funnel role, and capacity to decide where and how to sell."}, {"id": "11436688-a84e-4681-a902-3ce00440c570", "type": "subtopic", "title": "Channel economics and direct-booking value", "children": [{"id": "b8b79b2b-fffb-4ecd-b212-23486b378d85", "type": "concept", "title": "Commission, merchant discount, media cost, loyalty cost, cancellation, payment risk, service cost, and incremental labor"}, {"id": "e56a1f33-9cae-4010-adf8-9b5a77348844", "type": "concept", "title": "Customer acquisition cost, contribution per booking, net RevPAR/revenue, repeat direct behavior, and lifetime value"}, {"id": "e560ce6e-da82-45f1-8f52-3cd8ba8c7300", "type": "concept", "title": "Incrementality, displacement, cannibalization, assisted conversion, data ownership, and negotiation leverage"}], "description": "Students calculate net contribution rather than judging channels only by gross revenue or commission percentage."}]}, {"id": "f49bb5b0-7992-46f7-9fec-a73fb07c5472", "type": "topic", "title": "CRM, Loyalty, Personalization, and Relationship Economics", "description": "Relationship marketing seeks relevant, permissioned value over time. Students learn to design loyalty and CRM systems that improve the guest experience and business economics without treating data collection as a substitute for trust.", "children": [{"id": "6b44544d-1f39-4dde-a43a-7fd8c0d01118", "type": "subtopic", "title": "CRM architecture and lifecycle management", "children": [{"id": "760253ad-701a-45bb-9f06-a8a44df44130", "type": "concept", "title": "Profiles, identity resolution, reservation/POS/PMS interactions, preferences, cases, campaigns, and suppression rules"}, {"id": "539aac9d-17b8-42fd-a97a-5e9bc761e87a", "type": "concept", "title": "Acquisition, onboarding, pre-arrival, in-stay/visit, post-stay, reactivation, retention, churn, and win-back"}, {"id": "804e87dd-ceec-4e4a-97f2-e0977e3e8eec", "type": "concept", "title": "Segments, triggers, journeys, next-best action, contact policy, frequency caps, service recovery, and sales follow-up"}], "description": "Students organize first-party data, consent, identity, preferences, interactions, and service history around actionable guest relationships."}, {"id": "31d4f4f2-e650-4418-935a-106c0a17047c", "type": "subtopic", "title": "Loyalty-program design", "children": [{"id": "0d3bf19a-6004-409c-9f49-c3815b958e94", "type": "concept", "title": "Points, tiers, benefits, earn/burn, redemption, breakage, liability, partners, and elite recognition"}, {"id": "2f4073b6-8a2a-40c0-b909-781363cab0c4", "type": "concept", "title": "Member rates, experiences, upgrades, access, surprise and delight, gamification, coalition, and paid membership"}, {"id": "9dda798e-c137-4a1f-96e4-1a149bb288bf", "type": "concept", "title": "Enrollment, activation, engagement, retention, incremental spend, direct shift, redemption, cost, and fairness"}], "description": "This subtopic compares recognition, convenience, access, status, community, and economic rewards across different hospitality models."}, {"id": "afbcb6b5-5443-4d53-8069-f4f12a244dc8", "type": "subtopic", "title": "Personalization and lifetime value", "children": [{"id": "ea59aff4-b5d6-4a65-a570-df44e740d472", "type": "concept", "title": "Rules-based, predictive, contextual, human-led, real-time, and generative personalization"}, {"id": "b33ab2fe-c94d-4867-91e5-8533c8b27534", "type": "concept", "title": "Recency, frequency, monetary value, cohort retention, churn probability, contribution, CAC, and CLV"}, {"id": "49739436-b9c2-475b-ba7a-50233254c672", "type": "concept", "title": "Holdouts, incremental lift, privacy, sensitive attributes, proxy discrimination, creepiness, transparency, and guest control"}], "description": "Students distinguish helpful relevance from intrusive targeting and link relationship choices to future contribution."}]}, {"id": "8e51c788-35e0-4352-8b8a-2898e997544f", "type": "topic", "title": "Pricing, Promotions, and Commercial Strategy", "description": "Marketing, sales, distribution, and revenue management jointly shape profitable demand. Students evaluate price and promotions as signals, exchange terms, and capacity-allocation tools—not simply discounts.", "children": [{"id": "f53631bf-a9f1-4921-903c-fe6006ea4bf2", "type": "subtopic", "title": "Pricing foundations and guest perception", "children": [{"id": "753132b4-a56f-4c87-812f-047d9cb2e3fb", "type": "concept", "title": "Cost-plus, competitive, value-based, dynamic, package, subscription, membership, and auction approaches"}, {"id": "2b9b9889-81fa-4b20-aad5-7a5b8ff165ad", "type": "concept", "title": "Willingness to pay, elasticity, rate fences, versioning, anchoring, framing, decoys, and price-quality inference"}, {"id": "6a8f7cb2-2971-41e5-8cfc-677bba1f6310", "type": "concept", "title": "Fees, taxes, service charges, resort/destination fees, transparency, drip pricing risk, accessibility, and fairness"}], "description": "Students integrate cost, competition, demand, value, elasticity, reference prices, fairness, and brand position."}, {"id": "3070e729-5768-4af5-b662-62f1246fbd0b", "type": "subtopic", "title": "Promotion design and evaluation", "children": [{"id": "b43f1a56-951a-477f-9f12-6b45e2719800", "type": "concept", "title": "Discounts, packages, value-adds, coupons, codes, flash sales, gift cards, contests, and loyalty offers"}, {"id": "43fcd366-1b63-48da-9417-a73a05d7a1f4", "type": "concept", "title": "Objective, eligibility, fence, timing, inventory, blackout, terms, channel, redemption, fulfillment, and control"}, {"id": "8adc833f-9c85-400e-8086-81f3cdc4f936", "type": "concept", "title": "Incremental demand, contribution, displacement, cannibalization, pull-forward, repeat behavior, abuse, and post-promotion analysis"}], "description": "This subtopic separates a compelling tactical offer from permanent margin leakage or brand dilution."}, {"id": "4eb7edba-81ac-43d7-b58c-1a8b416ff00d", "type": "subtopic", "title": "Commercial integration", "children": [{"id": "b4b9c487-c6fc-4353-9bd2-49cac2402464", "type": "concept", "title": "Demand calendar, forecast, pace, pickup, need periods, segment/channel mix, group pipeline, and capacity"}, {"id": "e2ce1638-0262-417a-a210-1f48e027b640", "type": "concept", "title": "Campaign-response assumptions, lead time, conversion, cancellation, no-show, length of stay, ancillary spend, and flow-through"}, {"id": "36890810-ae5a-4baa-964e-540df49c929a", "type": "concept", "title": "Commercial meetings, shared metrics, decision rights, test-and-learn backlog, tradeoffs, and forecast feedback"}], "description": "Students align marketing demand generation with revenue decisions, sales pipelines, inventory, operations, and profit goals."}]}, {"id": "6be0cf96-ac8b-4672-afba-9f3f0e257323", "type": "topic", "title": "Reputation, Reviews, Service Recovery, and Crisis Communication", "description": "Hospitality reputation is produced by real experiences and amplified by platforms, media, and word of mouth. Students learn to listen, respond, recover, and improve without manipulating the evidence guests depend on.", "children": [{"id": "9a382833-871d-497d-a337-07ddf64cd115", "type": "subtopic", "title": "Review and reputation intelligence", "children": [{"id": "7f8035b8-79d0-41db-ba7d-a044b856086b", "type": "concept", "title": "Review sources, verified stays, sampling, recency, volume, score distribution, sentiment, topics, and language"}, {"id": "d6fc0766-184d-4ee1-9f7d-c12cd3d53f18", "type": "concept", "title": "Operational root causes, expectations, property/outlet/segment differences, trends, alerts, and closed-loop ownership"}, {"id": "b715f6db-a5a1-44db-8ab0-04263c81b614", "type": "concept", "title": "Benchmark comparability, platform rules, fake-review signals, incentives, moderation, and evidentiary limits"}], "description": "Students analyze rating distributions, volume, recency, text, themes, response patterns, and competitor context."}, {"id": "6a12c8eb-1076-4952-8da3-e1a8e1f92a97", "type": "subtopic", "title": "Response and service recovery", "children": [{"id": "087f427d-8dcb-4b65-929f-9e7fbbb4e497", "type": "concept", "title": "Listen, acknowledge, apologize where appropriate, explain without defensiveness, resolve, follow up, and document"}, {"id": "a600a62a-baa8-42c6-80b2-d824a7c8f9a2", "type": "concept", "title": "Public versus private response, personal data, safety, discrimination, threats, charge disputes, legal escalation, and employee support"}, {"id": "5b1eb0c8-daac-4b9f-bf63-083833dab77d", "type": "concept", "title": "Recovery authority, compensation guardrails, case routing, root-cause coding, learning review, and prevention"}], "description": "This subtopic develops timely, human, privacy-aware responses that acknowledge experience, solve what can be solved, and feed operational learning."}, {"id": "656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f", "type": "subtopic", "title": "Crisis and issues communication", "children": [{"id": "4e2afcd2-01a3-446f-8a15-684eaeb30a2c", "type": "concept", "title": "Crisis team, stakeholder map, holding statement, facts, approvals, spokesperson, channels, accessibility, and cadence"}, {"id": "7029ed7c-7efa-497c-8482-89afdccc25fc", "type": "concept", "title": "Safety, weather, cyber events, health, labor, discrimination, influencer incidents, operational disruption, and misinformation"}, {"id": "d566eed4-bcf8-464c-ac35-8d4360199ccc", "type": "concept", "title": "Speed versus certainty, empathy, rumor control, media monitoring, correction, recovery narrative, and after-action review"}], "description": "Students prepare for sudden events that affect safety, trust, access, operations, employees, destinations, or brand meaning."}]}, {"id": "0d0d1de8-bb81-460b-b0f4-11c27afccb24", "type": "topic", "title": "Marketing Analytics, Experimentation, Attribution, and ROI", "description": "Measurement should improve decisions, not merely decorate reports. Students build a metric system from business objective to guest behavior, financial outcome, causal evidence, and action.", "children": [{"id": "0b5272f9-ee28-4a49-9bde-58fb582dafca", "type": "subtopic", "title": "Measurement architecture and funnel", "children": [{"id": "14b25a3a-f8b3-4b8d-9eb6-fa6ef29771e7", "type": "concept", "title": "Objective, KPI, diagnostic metric, dimension, event, source, owner, target, threshold, and decision rule"}, {"id": "21b7ce08-ca54-4abf-96cf-08ecbd1b2183", "type": "concept", "title": "Reach, frequency, engagement, sessions, qualified traffic, leads, booking starts, conversion, revenue, cancellation, and retention"}, {"id": "0109e82c-3a6e-4f71-ba29-54d53149b520", "type": "concept", "title": "Metric dictionary, UTM taxonomy, campaign naming, tag plan, data layer, QA, reconciliation, latency, and versioning"}], "description": "Students define observable events and consistent metrics across awareness, consideration, booking, experience, retention, and advocacy."}, {"id": "3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d", "type": "subtopic", "title": "Economics and performance analysis", "children": [{"id": "13fe4148-cb8d-42bd-8978-7dc916112cc9", "type": "concept", "title": "CPM, CPC, cost per lead, cost per acquisition, ROAS, marketing ROI, contribution, payback, and lifetime value"}, {"id": "feec25ae-7b86-4874-a3b2-16327a9cbfc7", "type": "concept", "title": "Budget, marginal return, saturation, diminishing returns, portfolio allocation, scenario, sensitivity, and opportunity cost"}, {"id": "b1d8d5ee-ae64-4dd5-bfbc-80a640b9b44f", "type": "concept", "title": "Segment, channel, market, creative, device, cohort, property, outlet, and period analysis"}], "description": "This subtopic connects media and campaign performance to contribution rather than stopping at impressions, clicks, or gross revenue."}, {"id": "6d6ef760-be6d-477a-887e-88b54205b15f", "type": "subtopic", "title": "Experiments, attribution, and incrementality", "children": [{"id": "80fca97e-c271-4fa1-b1ba-ffa09b8f0728", "type": "concept", "title": "A/B and multivariate tests, randomized holdouts, geo tests, pre/post, matched markets, sample size, power, and guardrails"}, {"id": "40921dc7-2f6e-41b5-affc-6e7b47bde1d5", "type": "concept", "title": "Last-click, rules-based, data-driven, multi-touch, view-through, modeled events, lookback windows, and walled gardens"}, {"id": "bf8c85b1-6cab-4357-aa7d-fae14bc884cb", "type": "concept", "title": "Incremental lift, selection bias, spillover, novelty, seasonality, statistical versus managerial significance, and replication"}], "description": "Students distinguish correlation from causation and interpret platform attribution with appropriate skepticism."}]}, {"id": "b43403db-4520-44c1-b9bd-f93816e90764", "type": "topic", "title": "Ethics, Privacy, Responsible AI, Sustainability, and Trust", "description": "Marketing power carries duties to guests, employees, communities, partners, and the brand. Students evaluate whether a tactic is lawful, truthful, inclusive, secure, environmentally credible, and worthy of trust—not merely whether it performs.", "children": [{"id": "b655baa9-cc8d-419b-9eae-41da4adff42c", "type": "subtopic", "title": "Truthful and fair marketing", "children": [{"id": "ffbf0e37-16c3-4714-9710-19893e03c362", "type": "concept", "title": "Claim substantiation, clear and conspicuous disclosures, material connections, native ads, endorsements, and testimonials"}, {"id": "949c56b7-ac69-45e4-b4cf-4e267c3f0241", "type": "concept", "title": "FTC Consumer Review Rule, fake or AI-generated reviews, review suppression, incentives, insider reviews, and threats"}, {"id": "a19a7114-63cc-4843-affc-ff3501952991", "type": "concept", "title": "Dark patterns, false urgency, misleading availability, hidden conditions, drip pricing, vulnerable audiences, and documentation"}], "description": "Students apply U.S. truth-in-advertising principles to claims, endorsements, reviews, prices, promotions, scarcity, and targeting."}, {"id": "b6686f28-9d9d-423d-9ab2-875883e90fb4", "type": "subtopic", "title": "Privacy, security, and data governance", "children": [{"id": "17934b43-abd2-47b5-8486-69ffe8b44ec9", "type": "concept", "title": "First-, second-, and third-party data; consent; notice; preference; deletion; access; portability; and opt-out concepts"}, {"id": "ed8e1b05-09d3-4282-8375-02703a8509ef", "type": "concept", "title": "Sensitive data, location, children, biometrics, accessibility needs, payment, identity, loyalty, and employee information"}, {"id": "c98b3642-86fc-4ca5-a0ff-e49908cae6cb", "type": "concept", "title": "Data inventory, lawful purpose, minimization, retention, role-based access, vendor contracts, breach response, and state-law review"}], "description": "This subtopic teaches data minimization, purpose limitation, access control, retention, and vendor oversight in a changing legal environment."}, {"id": "cc8e6573-3b8a-4556-8df8-6984a8faf1e0", "type": "subtopic", "title": "Responsible AI and credible sustainability", "children": [{"id": "df8a1f1a-2f58-4c18-b959-7ce34c5ce9c4", "type": "concept", "title": "Generative content, translation, personalization, recommendations, forecasting, social listening, synthetic media, and agents"}, {"id": "2230deda-01c1-4174-8659-5698ab03949d", "type": "concept", "title": "Accuracy, hallucination, bias, representational harm, intellectual property, disclosure, prompt/data leakage, monitoring, and human approval"}, {"id": "7cfe818c-ff79-4cfd-83d2-997c2cfc53d4", "type": "concept", "title": "Environmental and social claims, boundaries, baselines, materiality, substantiation, greenwashing, community impact, and accessible benefits"}], "description": "Students use AI and sustainability claims with accountable human judgment, evidence, testing, and transparency."}]}, {"id": "598d1376-2f54-43b2-a081-b3b021f5a388", "type": "topic", "title": "Integrated Hospitality Marketing Plan and Campaign Execution", "description": "The capstone integrates analysis, choice, creative strategy, channels, operations, economics, governance, measurement, and learning. The plan is a decision system with owners and contingencies—not a slide deck of disconnected tactics.", "children": [{"id": "11cd3cda-038c-4b5f-b5f9-4a7a8aaf44e0", "type": "subtopic", "title": "Situation, objectives, and strategy", "children": [{"id": "e5ea14cd-647c-4301-9c1e-84de92562e14", "type": "concept", "title": "Business context, performance baseline, research insight, market opportunity, problem statement, and assumptions"}, {"id": "38a1cc51-4874-4118-b306-557ea5e6663e", "type": "concept", "title": "SMART objectives, target segments, positioning, value proposition, offer, competitive response, and strategic choices"}, {"id": "94431bcc-48e0-412c-bfdf-f65cde3e5081", "type": "concept", "title": "SWOT used as synthesis, risks, constraints, dependencies, stakeholder impacts, and success conditions"}], "description": "Students synthesize internal, customer, competitor, channel, and environmental evidence into a focused strategic diagnosis."}, {"id": "e6abc448-00bb-4fa9-87c8-4ea5eeac0eb6", "type": "subtopic", "title": "Tactics, resources, and implementation", "children": [{"id": "7cff85a9-9c61-4328-ad04-2d88d8972b06", "type": "concept", "title": "Journey, message hierarchy, creative idea, content, media, PR, sales, distribution, CRM, loyalty, and partnerships"}, {"id": "c3abf166-e68c-4c0b-8b2f-569a1a2d66be", "type": "concept", "title": "Budget, calendar, work breakdown, owners, approvals, assets, technology, vendors, training, capacity, and service readiness"}, {"id": "21a6cdce-05b1-4500-87fd-64b2b2925b20", "type": "concept", "title": "RACI, governance, brand/legal/privacy review, accessibility QA, launch checklist, escalation, and contingency plan"}], "description": "This subtopic translates strategy into a coordinated campaign and operating plan that can actually be delivered."}, {"id": "2637cd0d-3d4a-449e-a976-5f169f0e7fe0", "type": "subtopic", "title": "Measurement, optimization, and defense", "children": [{"id": "409a7b40-d79c-4412-92f4-9419d655fcb8", "type": "concept", "title": "KPI tree, targets, dashboard, data sources, attribution, experiments, holdouts, forecast, and financial case"}, {"id": "48c2e214-5e1d-4772-a97f-cbef8db92959", "type": "concept", "title": "Review cadence, alerts, optimization rules, learning agenda, budget shifts, stop/scale criteria, and post-campaign review"}, {"id": "e9e8142a-049a-4cf7-9bbb-d96ce75a4e45", "type": "concept", "title": "Executive summary, oral defense, limitations, alternative strategies, stakeholder questions, and implementation recommendation"}], "description": "Students specify how evidence will change decisions and defend their plan against commercial, operational, ethical, and analytical challenges."}]}], "dbBacked": true}$hmktjson$::jsonb,
