insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b7b1856c-b6f6-441b-af29-5042d2f550e3', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Hospitality Marketing, Service Logic, and Strategic Value', 'Hospitality marketing creates and communicates value before, during, and after a guest experience. This section frames marketing as an enterprise discipline that connects guest needs, operations, revenue, brand promises, and long-term relationships.', 0),
  ('1e39d3f3-1529-4471-8bcf-12935d4672dd', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b7b1856c-b6f6-441b-af29-5042d2f550e3', 'subtopic'::public.curated_course_node_type, 'Services-marketing fundamentals', 'Students learn why intangible, variable, perishable, and co-produced experiences require different choices from packaged goods.', 0),
  ('3b4dfac1-415c-488f-8d49-d7fb6aa60e81', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '1e39d3f3-1529-4471-8bcf-12935d4672dd', 'concept'::public.curated_course_node_type, 'Intangibility, inseparability, variability, perishability, ownership, and perceived risk', null, 0),
  ('300b4877-6474-434e-8ca0-9d6f30ea8641', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '1e39d3f3-1529-4471-8bcf-12935d4672dd', 'concept'::public.curated_course_node_type, 'The expanded service mix: product, price, place, promotion, people, process, and physical evidence', null, 1),
  ('0b842042-4e79-4073-b88d-b809aa9b076a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '1e39d3f3-1529-4471-8bcf-12935d4672dd', 'concept'::public.curated_course_node_type, 'Expectation formation, moments of truth, service scripts, signaling, guarantees, and recovery', null, 2),
  ('a3a34072-f8e9-4ace-b7c7-00795a3f1d56', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b7b1856c-b6f6-441b-af29-5042d2f550e3', 'subtopic'::public.curated_course_node_type, 'Market orientation and value creation', 'This subtopic turns guest, competitor, and operational evidence into a coherent value proposition and strategic direction.', 1),
  ('fe34511f-b883-40f5-a63f-3418c9ceb18c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'a3a34072-f8e9-4ace-b7c7-00795a3f1d56', 'concept'::public.curated_course_node_type, 'Customer orientation, competitor orientation, cross-functional coordination, learning, and responsiveness', null, 0),
  ('c25b2c86-a1df-4390-ba5c-894338219478', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'a3a34072-f8e9-4ace-b7c7-00795a3f1d56', 'concept'::public.curated_course_node_type, 'Customer value, benefits, sacrifices, jobs-to-be-done, differentiation, parity, and switching costs', null, 1),
  ('ebdc000b-6a26-4ad7-b01c-761fb85bbff6', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'a3a34072-f8e9-4ace-b7c7-00795a3f1d56', 'concept'::public.curated_course_node_type, 'Mission, objectives, capabilities, constraints, stakeholder value, and marketing''s role in profitable demand', null, 2),
  ('94da44da-efab-478d-9492-14ecf3251873', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b7b1856c-b6f6-441b-af29-5042d2f550e3', 'subtopic'::public.curated_course_node_type, 'Hospitality sectors and business models', 'Students compare how marketing economics change across lodging, foodservice, clubs, events, attractions, travel, and destinations.', 2),
  ('4768925b-e8d9-4c5a-99b4-5ad0d5befca1', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '94da44da-efab-478d-9492-14ecf3251873', 'concept'::public.curated_course_node_type, 'Hotels, resorts, restaurants, vacation rentals, clubs, casinos, cruises, venues, and destinations', null, 0),
  ('787c1520-03c1-44fb-aeaf-46b34353a35e', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '94da44da-efab-478d-9492-14ecf3251873', 'concept'::public.curated_course_node_type, 'Owned, managed, franchised, licensed, independent, platform, membership, and asset-light models', null, 1),
  ('239fd64c-5583-43ce-a3c9-37c60f2a2c2a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '94da44da-efab-478d-9492-14ecf3251873', 'concept'::public.curated_course_node_type, 'Demand perishability, fixed capacity, seasonality, ancillary revenue, labor intensity, and network effects', null, 2),
  ('108b2414-4178-4370-bb5b-ccf90920ab37', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Consumer Behavior, Research, and Market Intelligence', 'Strong hospitality marketing starts with disciplined curiosity about people, context, and demand. Students learn to replace assumptions with evidence while respecting research ethics and the limits of available data.', 1),
  ('11c715ec-ad2f-4750-ba22-7ee221ec2171', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '108b2414-4178-4370-bb5b-ccf90920ab37', 'subtopic'::public.curated_course_node_type, 'Guest decision behavior', 'Students examine how motivation, perception, memory, emotion, culture, social influence, and risk shape hospitality choice and evaluation.', 0),
  ('9719617d-14d4-4749-8feb-89dab219148d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11c715ec-ad2f-4750-ba22-7ee221ec2171', 'concept'::public.curated_course_node_type, 'Need recognition, information search, consideration sets, booking, consumption, evaluation, sharing, and repeat behavior', null, 0),
  ('d525f9cb-4019-41f0-8e94-fd78b91a8624', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11c715ec-ad2f-4750-ba22-7ee221ec2171', 'concept'::public.curated_course_node_type, 'Functional, emotional, social, sensory, experiential, and transformative benefits', null, 1),
  ('3d9808b3-20e6-4e20-a92c-beee19b6834f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11c715ec-ad2f-4750-ba22-7ee221ec2171', 'concept'::public.curated_course_node_type, 'Reference groups, household roles, culture, identity, accessibility needs, travel party, occasion, and situational factors', null, 2),
  ('d2f1d090-0c00-45d3-9e59-febc163cb713', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '108b2414-4178-4370-bb5b-ccf90920ab37', 'subtopic'::public.curated_course_node_type, 'Marketing research design', 'This subtopic develops the ability to turn a managerial problem into an answerable research question and credible evidence plan.', 1),
  ('02c8ef66-2e92-4017-b6ca-cdb7960d1140', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd2f1d090-0c00-45d3-9e59-febc163cb713', 'concept'::public.curated_course_node_type, 'Decision problem, research question, hypotheses, constructs, measures, sampling, and analysis plan', null, 0),
  ('49eba0c6-cab6-43cd-93c8-a1ec827abc58', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd2f1d090-0c00-45d3-9e59-febc163cb713', 'concept'::public.curated_course_node_type, 'Exploratory, descriptive, causal, qualitative, quantitative, observational, survey, interview, focus group, and experiment methods', null, 1),
  ('1d7043a7-3647-4886-b9d1-7d2fb7f0e449', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd2f1d090-0c00-45d3-9e59-febc163cb713', 'concept'::public.curated_course_node_type, 'Validity, reliability, bias, confounding, nonresponse, representativeness, triangulation, and ethical consent', null, 2),
  ('c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '108b2414-4178-4370-bb5b-ccf90920ab37', 'subtopic'::public.curated_course_node_type, 'Market and competitor intelligence', 'Students assemble demand, competitor, channel, trend, and internal evidence without confusing a benchmark with a strategy.', 2),
  ('5b208697-c7ad-45b4-a432-587592053cf0', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db', 'concept'::public.curated_course_node_type, 'Market size, growth, share, penetration, demand drivers, seasonality, source markets, and trip purpose', null, 0),
  ('967a7828-9358-48d2-af59-2c4e60566810', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db', 'concept'::public.curated_course_node_type, 'Competitive sets, rate/product audits, review mining, social listening, search trends, and mystery shopping', null, 1),
  ('de45dc19-a114-4917-bd14-26f3012961ee', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c9752ca3-a40a-4c6d-b6a9-a5ce35bd33db', 'concept'::public.curated_course_node_type, 'PESTLE, five forces, scenario signals, source quality, freshness, comparability, and uncertainty', null, 2),
  ('894704ee-4042-42a2-a1af-ea09c90d1c94', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Segmentation, Targeting, Positioning, and Personas', 'Segmentation concentrates resources on meaningfully different needs and behaviors. Students learn to select attractive targets and create a position that can be delivered consistently—not merely write colorful personas.', 2),
  ('ab636d9c-a303-41e8-95d6-c66f33751f02', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '894704ee-4042-42a2-a1af-ea09c90d1c94', 'subtopic'::public.curated_course_node_type, 'Segmentation design', 'Students divide markets using variables that predict needs, choice, value, or response and that managers can actually reach and serve.', 0),
  ('9098ff59-7d8c-4e98-bfbc-47a03500ad6f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'ab636d9c-a303-41e8-95d6-c66f33751f02', 'concept'::public.curated_course_node_type, 'Geographic, demographic, psychographic, behavioral, occasion, benefit, needs-based, firmographic, and value segments', null, 0),
  ('bfebd93d-6add-4875-99fd-7d770f90bf73', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'ab636d9c-a303-41e8-95d6-c66f33751f02', 'concept'::public.curated_course_node_type, 'Individual traveler, household, group, corporate account, intermediary, event planner, member, and local resident units', null, 1),
  ('b519365b-6d89-4b8f-a180-2064846b0951', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'ab636d9c-a303-41e8-95d6-c66f33751f02', 'concept'::public.curated_course_node_type, 'Identifiability, substantiality, stability, accessibility, differentiability, actionability, privacy, and fairness', null, 2),
  ('c13fd011-6e5a-4e5d-afae-5dae53f23eee', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '894704ee-4042-42a2-a1af-ea09c90d1c94', 'subtopic'::public.curated_course_node_type, 'Target-market selection', 'This subtopic compares segment attractiveness with strategic fit, cost to serve, capacity, risk, and likely lifetime economics.', 1),
  ('8834b530-0881-432f-a940-73aec35dda93', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c13fd011-6e5a-4e5d-afae-5dae53f23eee', 'concept'::public.curated_course_node_type, 'Market potential, growth, competition, price sensitivity, acquisition cost, retention, ancillary spend, and seasonality', null, 0),
  ('d931f311-4d7e-432c-aae5-b2a9d55d2c1c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c13fd011-6e5a-4e5d-afae-5dae53f23eee', 'concept'::public.curated_course_node_type, 'Undifferentiated, differentiated, concentrated, local, niche, account-based, and one-to-one strategies', null, 1),
  ('7adff2e8-37bd-413a-92ed-6abb968bdbea', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c13fd011-6e5a-4e5d-afae-5dae53f23eee', 'concept'::public.curated_course_node_type, 'Primary, secondary, exclusion, priority, capacity allocation, cannibalization, and portfolio balance', null, 2),
  ('56f7a2fe-7d2a-4526-9065-b4efc5f10b85', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '894704ee-4042-42a2-a1af-ea09c90d1c94', 'subtopic'::public.curated_course_node_type, 'Positioning and evidence-based personas', 'Students turn research into a differentiated promise, reasons to believe, and practical decision tools for teams.', 2),
  ('7399b8a4-95e5-42f8-b6df-4db6f98a878a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '56f7a2fe-7d2a-4526-9065-b4efc5f10b85', 'concept'::public.curated_course_node_type, 'Frame of reference, target, insight, benefit, points of difference, points of parity, proof, and brand essence', null, 0),
  ('4d0665a4-cbc1-4f59-8f1e-0fdca3b4ba62', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '56f7a2fe-7d2a-4526-9065-b4efc5f10b85', 'concept'::public.curated_course_node_type, 'Perceptual maps, value curves, positioning statements, message hierarchy, and competitive response', null, 1),
  ('9b6b099f-9de0-4ec3-bb77-6169a840b3e7', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '56f7a2fe-7d2a-4526-9065-b4efc5f10b85', 'concept'::public.curated_course_node_type, 'Persona goals, behaviors, barriers, context, evidence, uncertainty, anti-stereotyping, and update cadence', null, 2),
  ('d648e2ca-b80c-4f49-b9ea-28ebdf942862', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Brand Strategy, Architecture, and Experience Design', 'A hospitality brand is a memory structure and an operating promise. This section connects identity and communications to standards, spaces, people, technology, partnerships, and the economics of a brand portfolio.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('bcf956a0-29ab-4c70-9010-2be331fa8fb7', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd648e2ca-b80c-4f49-b9ea-28ebdf942862', 'subtopic'::public.curated_course_node_type, 'Brand identity and equity', 'Students learn how awareness, associations, perceived quality, trust, meaning, and loyalty create preference and pricing power.', 0),
  ('71665230-8a6a-4fe3-8ede-2fbaf45b7f24', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'bcf956a0-29ab-4c70-9010-2be331fa8fb7', 'concept'::public.curated_course_node_type, 'Purpose, values, personality, voice, visual identity, symbols, sensory codes, story, and heritage', null, 0),
  ('afcb6a7f-c2d9-4394-91c1-063e84bc8872', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'bcf956a0-29ab-4c70-9010-2be331fa8fb7', 'concept'::public.curated_course_node_type, 'Salience, imagery, judgments, feelings, resonance, familiarity, distinctiveness, and mental availability', null, 1),
  ('528ff1ae-f674-43fc-a802-562b52766cea', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'bcf956a0-29ab-4c70-9010-2be331fa8fb7', 'concept'::public.curated_course_node_type, 'Brand tracking, preference, consideration, price premium, advocacy, reputation, and financial contribution', null, 2),
  ('4cae028c-d45e-421f-b245-f4a655e8db8a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd648e2ca-b80c-4f49-b9ea-28ebdf942862', 'subtopic'::public.curated_course_node_type, 'Brand architecture and portfolios', 'This subtopic clarifies relationships among corporate, master, endorsed, collection, sub-brand, property, outlet, and partner brands.', 1),
  ('fef01e6e-3265-41eb-a3b6-07b3b4e392c6', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4cae028c-d45e-421f-b245-f4a655e8db8a', 'concept'::public.curated_course_node_type, 'Branded house, house of brands, endorsed brands, soft brands, collections, and independent affiliation', null, 0),
  ('956b4397-e138-4fca-9b36-5229d1a8d8e0', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4cae028c-d45e-421f-b245-f4a655e8db8a', 'concept'::public.curated_course_node_type, 'Segment coverage, overlap, cannibalization, extension, licensing, franchising, conversion, and brand standards', null, 1),
  ('209f137b-363e-4663-aab9-b3a07b53a6e8', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4cae028c-d45e-421f-b245-f4a655e8db8a', 'concept'::public.curated_course_node_type, 'Owner, operator, brand, franchisee, destination, chef, venue, and co-brand governance', null, 2),
  ('c213da86-9bd3-4c61-97aa-32d902376ad3', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'd648e2ca-b80c-4f49-b9ea-28ebdf942862', 'subtopic'::public.curated_course_node_type, 'Experience and physical-evidence design', 'Students translate positioning into the visible and invisible cues that make the promise credible at every touchpoint.', 2),
  ('205f4e15-0f3a-4591-91f5-30f8b51ae0b4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c213da86-9bd3-4c61-97aa-32d902376ad3', 'concept'::public.curated_course_node_type, 'Servicescape, atmosphere, sensory design, signage, collateral, uniforms, interface, accessibility, and wayfinding', null, 0),
  ('2f17aa85-67fb-4444-930d-cd95d6520b08', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c213da86-9bd3-4c61-97aa-32d902376ad3', 'concept'::public.curated_course_node_type, 'Brand standards, service rituals, scripts, personalization, local authenticity, employee enablement, and empowerment', null, 1),
  ('b8c2a201-57ba-4332-806f-e8c6a9f508b3', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c213da86-9bd3-4c61-97aa-32d902376ad3', 'concept'::public.curated_course_node_type, 'Concept testing, prototyping, blueprinting, consistency, adaptation, maintenance, and experience measurement', null, 2),
  ('2d9aeef6-0613-4fc9-bd30-c2f79ec377b4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Customer Journey, Service Quality, and Inclusive Experience', 'Journey management reveals how many teams and platforms shape one guest relationship. Students diagnose friction, design accessible experiences, and close the loop between promised and delivered service.', 4),
  ('70d1f169-2e31-4e06-99a4-762f050d5517', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '2d9aeef6-0613-4fc9-bd30-c2f79ec377b4', 'subtopic'::public.curated_course_node_type, 'Journey mapping and service blueprinting', 'Students map guest goals, actions, emotions, channels, handoffs, backstage processes, systems, and failure points.', 0),
  ('b923be61-a9f2-438d-86a2-b0b48975b539', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '70d1f169-2e31-4e06-99a4-762f050d5517', 'concept'::public.curated_course_node_type, 'Dreaming, planning, search, booking, pre-arrival, arrival, stay/visit, departure, post-stay, and return', null, 0),
  ('963f434b-856b-410e-8445-40e1a78914eb', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '70d1f169-2e31-4e06-99a4-762f050d5517', 'concept'::public.curated_course_node_type, 'Touchpoints, moments of truth, pain points, delight, effort, wait, uncertainty, handoffs, and channel switching', null, 1),
  ('2a6781e0-274a-49ed-b36b-1eb901e29d49', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '70d1f169-2e31-4e06-99a4-762f050d5517', 'concept'::public.curated_course_node_type, 'Frontstage, backstage, support process, data flow, ownership, service standards, and recovery triggers', null, 2),
  ('fae7bdfe-0261-4eff-b31d-5c4685f4a677', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '2d9aeef6-0613-4fc9-bd30-c2f79ec377b4', 'subtopic'::public.curated_course_node_type, 'Service quality and experience measurement', 'This subtopic combines perception and operational evidence to understand whether the experience met relevant expectations.', 1),
  ('1aa02b63-b02d-47af-ad18-ca4b1a916d3d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'fae7bdfe-0261-4eff-b31d-5c4685f4a677', 'concept'::public.curated_course_node_type, 'Reliability, responsiveness, assurance, empathy, tangibles, outcome quality, process quality, and value', null, 0),
  ('f33dd84c-fc15-4e70-8631-5780344ba8a5', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'fae7bdfe-0261-4eff-b31d-5c4685f4a677', 'concept'::public.curated_course_node_type, 'Satisfaction, overall rating, recommendation, effort, sentiment, complaints, repeat intent, and observed behavior', null, 1),
  ('088ae46a-6169-49db-8954-1c984d9af5ff', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'fae7bdfe-0261-4eff-b31d-5c4685f4a677', 'concept'::public.curated_course_node_type, 'Expectation effects, survey timing, scale design, response bias, benchmarks, drivers, and qualitative context', null, 2),
