  ('ddf405c6-179c-4e54-ba64-16f7103cd722', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '5a72cb61-340d-43c4-929c-1fa41ddcd8f1', 'concept'::public.curated_course_node_type, 'Representation, localization, cultural humility, testing with affected users, employee training, and complaint learning', null, 2),
