  ('89a8ea8e-dcf5-4d95-8829-6e5bce6a17a1', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'e6c74ba0-9a3d-4f02-ba73-c17254267970', 'concept'::public.curated_course_node_type, 'Rooms, tables, menus, amenities, activities, events, memberships, packages, add-ons, and ancillary services', null, 0),
