  ('856cc486-636a-4dbf-90eb-259848d3dec2', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'e6c74ba0-9a3d-4f02-ba73-c17254267970', 'concept'::public.curated_course_node_type, 'Concept tests, minimum viable offer, operational feasibility, capacity, quality, safety, cost, and brand fit', null, 2),
  ('c2a77de9-3bce-420a-a36f-7624c1761ab2', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'e28e92ae-f1cd-4ebb-b7c6-bc44a8c40fcc', 'subtopic'::public.curated_course_node_type, 'Message and creative strategy', 'This subtopic turns a target insight and positioning into persuasive, distinctive, truthful creative work.', 1),
  ('12c991ce-61a3-4164-88d3-e5f9413df297', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c2a77de9-3bce-420a-a36f-7624c1761ab2', 'concept'::public.curated_course_node_type, 'Communication objective, audience, barrier, promise, support, tone, call to action, and mandatories', null, 0),
  ('9584589d-2c75-4fa7-83ac-3dea79bb592c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c2a77de9-3bce-420a-a36f-7624c1761ab2', 'concept'::public.curated_course_node_type, 'Awareness, comprehension, attitude, preference, intent, action, retention, advocacy, and hierarchy of effects', null, 1),
  ('cb53f045-7527-4e0b-a454-cf0839901d96', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c2a77de9-3bce-420a-a36f-7624c1761ab2', 'concept'::public.curated_course_node_type, 'Storytelling, imagery, social proof, scarcity, framing, emotional and rational appeals, pretesting, and adaptation', null, 2),
  ('f15c273f-1bf1-4209-a197-45c10c00ff89', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'e28e92ae-f1cd-4ebb-b7c6-bc44a8c40fcc', 'subtopic'::public.curated_course_node_type, 'Integrated communications and sales alignment', 'Students coordinate paid, owned, earned, shared, partner, public-relations, direct, experiential, and personal-selling activity.', 2),
  ('8d1a0648-f5ed-4813-b3d3-5bdcbd28a73e', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f15c273f-1bf1-4209-a197-45c10c00ff89', 'concept'::public.curated_course_node_type, 'Advertising, PR, sales promotion, direct marketing, email, events, partnerships, sponsorships, and trade marketing', null, 0),
  ('4893ba9f-e908-40a9-9450-cb9f6166d678', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f15c273f-1bf1-4209-a197-45c10c00ff89', 'concept'::public.curated_course_node_type, 'Leisure, group, business travel, meetings, weddings, catering, corporate accounts, and destination sales', null, 1),
  ('670232cd-084a-49d5-ae0f-2bd759131928', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f15c273f-1bf1-4209-a197-45c10c00ff89', 'concept'::public.curated_course_node_type, 'Campaign architecture, channel roles, frequency, sequencing, calendar, sales enablement, lead handoff, and message consistency', null, 2),
  ('32a5dc29-923d-4417-9cc3-24b872c11cf3', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Digital Marketing, Content, Search, Social, and Influencers', 'Digital discovery and persuasion now span search, maps, websites, apps, social platforms, creators, video, email, and emerging interfaces. Students learn channel craft while retaining strategic control of audience, message, measurement, and risk.', 6),
  ('bdac3076-f516-4dc7-8578-c72976147393', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '32a5dc29-923d-4417-9cc3-24b872c11cf3', 'subtopic'::public.curated_course_node_type, 'Digital ecosystem and owned experience', 'Students evaluate how websites, booking engines, menus, maps, apps, email, messaging, and local listings move guests from intent to action.', 0);
