  ('e51967a8-236b-40e5-a745-84eb3dd20c9a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c3fa96e9-aea4-46cc-ac2b-fb9bbe5bfe32', 'concept'::public.curated_course_node_type, 'Rights, licensing, whitelisting, reuse, data access, cancellation, morality clauses, and crisis response', null, 1),
  ('05091798-bfd5-4547-b3ce-9bafff83ea04', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'c3fa96e9-aea4-46cc-ac2b-fb9bbe5bfe32', 'concept'::public.curated_course_node_type, 'FTC material-connection disclosure, truthful claims, authentic experience, monitoring, fraud signals, and outcome evaluation', null, 2),
  ('761eff3c-802c-446c-8aea-6eb69f5ca164', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Distribution, E-Commerce, and Channel Economics', 'Distribution determines where hospitality inventory is displayed, compared, booked, paid for, modified, and serviced. Students connect marketing reach and convenience to commissions, data access, parity, control, and lifetime guest value.', 7),
  ('2dc01842-c31c-4e89-b2fc-05de9f0d2339', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '761eff3c-802c-446c-8aea-6eb69f5ca164', 'subtopic'::public.curated_course_node_type, 'Hospitality distribution landscape', 'Students map direct and indirect routes from supplier inventory to leisure, corporate, group, and wholesale demand.', 0),
  ('43890243-b8d8-431d-a7a7-05e4dbaf5e9b', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '2dc01842-c31c-4e89-b2fc-05de9f0d2339', 'concept'::public.curated_course_node_type, 'Brand.com, property direct, voice, app, GDS, OTA, metasearch, wholesaler, tour operator, TMC, and consortia', null, 0),
