  ('7166ed63-a365-4b1e-b001-a7d95d64965d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '2dc01842-c31c-4e89-b2fc-05de9f0d2339', 'concept'::public.curated_course_node_type, 'Merchant, agency, opaque, package, allotment, free-sale, net-rate, commission, and transaction models', null, 2),
  ('350906a0-c3d7-4726-b16e-e23d9e612b2b', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '761eff3c-802c-446c-8aea-6eb69f5ca164', 'subtopic'::public.curated_course_node_type, 'Channel strategy and merchandising', 'This subtopic uses segment, market, need period, funnel role, and capacity to decide where and how to sell.', 1),
  ('35bef69c-0523-4c9a-9702-b725110533f2', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '350906a0-c3d7-4726-b16e-e23d9e612b2b', 'concept'::public.curated_course_node_type, 'Reach, conversion, placement, content quality, reviews, offers, loyalty/member rates, packages, and mobile deals', null, 0),
  ('259f2a95-a170-480d-974c-3cf9a73a6fbc', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '350906a0-c3d7-4726-b16e-e23d9e612b2b', 'concept'::public.curated_course_node_type, 'Rate parity, availability parity, closed-user groups, fences, attribution, leakage, conflict, and partner scorecards', null, 1),
  ('e8de5d04-9526-476f-bf29-8c1da0de8e53', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '350906a0-c3d7-4726-b16e-e23d9e612b2b', 'concept'::public.curated_course_node_type, 'Need dates, compression, shoulder periods, dayparts, geographic/source markets, and campaign-channel fit', null, 2),
  ('11436688-a84e-4681-a902-3ce00440c570', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '761eff3c-802c-446c-8aea-6eb69f5ca164', 'subtopic'::public.curated_course_node_type, 'Channel economics and direct-booking value', 'Students calculate net contribution rather than judging channels only by gross revenue or commission percentage.', 2),
  ('b8b79b2b-fffb-4ecd-b212-23486b378d85', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11436688-a84e-4681-a902-3ce00440c570', 'concept'::public.curated_course_node_type, 'Commission, merchant discount, media cost, loyalty cost, cancellation, payment risk, service cost, and incremental labor', null, 0),
  ('e56a1f33-9cae-4010-adf8-9b5a77348844', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11436688-a84e-4681-a902-3ce00440c570', 'concept'::public.curated_course_node_type, 'Customer acquisition cost, contribution per booking, net RevPAR/revenue, repeat direct behavior, and lifetime value', null, 1),
  ('e560ce6e-da82-45f1-8f52-3cd8ba8c7300', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11436688-a84e-4681-a902-3ce00440c570', 'concept'::public.curated_course_node_type, 'Incrementality, displacement, cannibalization, assisted conversion, data ownership, and negotiation leverage', null, 2),
  ('f49bb5b0-7992-46f7-9fec-a73fb07c5472', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'CRM, Loyalty, Personalization, and Relationship Economics', 'Relationship marketing seeks relevant, permissioned value over time. Students learn to design loyalty and CRM systems that improve the guest experience and business economics without treating data collection as a substitute for trust.', 8),
  ('6b44544d-1f39-4dde-a43a-7fd8c0d01118', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f49bb5b0-7992-46f7-9fec-a73fb07c5472', 'subtopic'::public.curated_course_node_type, 'CRM architecture and lifecycle management', 'Students organize first-party data, consent, identity, preferences, interactions, and service history around actionable guest relationships.', 0),
  ('760253ad-701a-45bb-9f06-a8a44df44130', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6b44544d-1f39-4dde-a43a-7fd8c0d01118', 'concept'::public.curated_course_node_type, 'Profiles, identity resolution, reservation/POS/PMS interactions, preferences, cases, campaigns, and suppression rules', null, 0),
  ('539aac9d-17b8-42fd-a97a-5e9bc761e87a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6b44544d-1f39-4dde-a43a-7fd8c0d01118', 'concept'::public.curated_course_node_type, 'Acquisition, onboarding, pre-arrival, in-stay/visit, post-stay, reactivation, retention, churn, and win-back', null, 1),
  ('804e87dd-ceec-4e4a-97f2-e0977e3e8eec', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6b44544d-1f39-4dde-a43a-7fd8c0d01118', 'concept'::public.curated_course_node_type, 'Segments, triggers, journeys, next-best action, contact policy, frequency caps, service recovery, and sales follow-up', null, 2),
  ('31d4f4f2-e650-4418-935a-106c0a17047c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f49bb5b0-7992-46f7-9fec-a73fb07c5472', 'subtopic'::public.curated_course_node_type, 'Loyalty-program design', 'This subtopic compares recognition, convenience, access, status, community, and economic rewards across different hospitality models.', 1),
  ('0d3bf19a-6004-409c-9f49-c3815b958e94', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '31d4f4f2-e650-4418-935a-106c0a17047c', 'concept'::public.curated_course_node_type, 'Points, tiers, benefits, earn/burn, redemption, breakage, liability, partners, and elite recognition', null, 0),
  ('2f4073b6-8a2a-40c0-b909-781363cab0c4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '31d4f4f2-e650-4418-935a-106c0a17047c', 'concept'::public.curated_course_node_type, 'Member rates, experiences, upgrades, access, surprise and delight, gamification, coalition, and paid membership', null, 1),
  ('9dda798e-c137-4a1f-96e4-1a149bb288bf', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '31d4f4f2-e650-4418-935a-106c0a17047c', 'concept'::public.curated_course_node_type, 'Enrollment, activation, engagement, retention, incremental spend, direct shift, redemption, cost, and fairness', null, 2),
  ('afbcb6b5-5443-4d53-8069-f4f12a244dc8', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f49bb5b0-7992-46f7-9fec-a73fb07c5472', 'subtopic'::public.curated_course_node_type, 'Personalization and lifetime value', 'Students distinguish helpful relevance from intrusive targeting and link relationship choices to future contribution.', 2),
  ('ea59aff4-b5d6-4a65-a570-df44e740d472', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'afbcb6b5-5443-4d53-8069-f4f12a244dc8', 'concept'::public.curated_course_node_type, 'Rules-based, predictive, contextual, human-led, real-time, and generative personalization', null, 0),
  ('b33ab2fe-c94d-4867-91e5-8533c8b27534', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'afbcb6b5-5443-4d53-8069-f4f12a244dc8', 'concept'::public.curated_course_node_type, 'Recency, frequency, monetary value, cohort retention, churn probability, contribution, CAC, and CLV', null, 1),
  ('49739436-b9c2-475b-ba7a-50233254c672', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'afbcb6b5-5443-4d53-8069-f4f12a244dc8', 'concept'::public.curated_course_node_type, 'Holdouts, incremental lift, privacy, sensitive attributes, proxy discrimination, creepiness, transparency, and guest control', null, 2),
  ('8e51c788-35e0-4352-8b8a-2898e997544f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Pricing, Promotions, and Commercial Strategy', 'Marketing, sales, distribution, and revenue management jointly shape profitable demand. Students evaluate price and promotions as signals, exchange terms, and capacity-allocation tools—not simply discounts.', 9),
  ('f53631bf-a9f1-4921-903c-fe6006ea4bf2', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '8e51c788-35e0-4352-8b8a-2898e997544f', 'subtopic'::public.curated_course_node_type, 'Pricing foundations and guest perception', 'Students integrate cost, competition, demand, value, elasticity, reference prices, fairness, and brand position.', 0),
  ('753132b4-a56f-4c87-812f-047d9cb2e3fb', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f53631bf-a9f1-4921-903c-fe6006ea4bf2', 'concept'::public.curated_course_node_type, 'Cost-plus, competitive, value-based, dynamic, package, subscription, membership, and auction approaches', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2b9b9889-81fa-4b20-aad5-7a5b8ff165ad', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f53631bf-a9f1-4921-903c-fe6006ea4bf2', 'concept'::public.curated_course_node_type, 'Willingness to pay, elasticity, rate fences, versioning, anchoring, framing, decoys, and price-quality inference', null, 1),
  ('6a8f7cb2-2971-41e5-8cfc-677bba1f6310', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'f53631bf-a9f1-4921-903c-fe6006ea4bf2', 'concept'::public.curated_course_node_type, 'Fees, taxes, service charges, resort/destination fees, transparency, drip pricing risk, accessibility, and fairness', null, 2),
  ('3070e729-5768-4af5-b662-62f1246fbd0b', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '8e51c788-35e0-4352-8b8a-2898e997544f', 'subtopic'::public.curated_course_node_type, 'Promotion design and evaluation', 'This subtopic separates a compelling tactical offer from permanent margin leakage or brand dilution.', 1),
  ('b43f1a56-951a-477f-9f12-6b45e2719800', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3070e729-5768-4af5-b662-62f1246fbd0b', 'concept'::public.curated_course_node_type, 'Discounts, packages, value-adds, coupons, codes, flash sales, gift cards, contests, and loyalty offers', null, 0),
  ('43fcd366-1b63-48da-9417-a73a05d7a1f4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3070e729-5768-4af5-b662-62f1246fbd0b', 'concept'::public.curated_course_node_type, 'Objective, eligibility, fence, timing, inventory, blackout, terms, channel, redemption, fulfillment, and control', null, 1),
  ('8adc833f-9c85-400e-8086-81f3cdc4f936', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3070e729-5768-4af5-b662-62f1246fbd0b', 'concept'::public.curated_course_node_type, 'Incremental demand, contribution, displacement, cannibalization, pull-forward, repeat behavior, abuse, and post-promotion analysis', null, 2),
  ('4eb7edba-81ac-43d7-b58c-1a8b416ff00d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '8e51c788-35e0-4352-8b8a-2898e997544f', 'subtopic'::public.curated_course_node_type, 'Commercial integration', 'Students align marketing demand generation with revenue decisions, sales pipelines, inventory, operations, and profit goals.', 2),
  ('b4b9c487-c6fc-4353-9bd2-49cac2402464', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4eb7edba-81ac-43d7-b58c-1a8b416ff00d', 'concept'::public.curated_course_node_type, 'Demand calendar, forecast, pace, pickup, need periods, segment/channel mix, group pipeline, and capacity', null, 0),
  ('e2ce1638-0262-417a-a210-1f48e027b640', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4eb7edba-81ac-43d7-b58c-1a8b416ff00d', 'concept'::public.curated_course_node_type, 'Campaign-response assumptions, lead time, conversion, cancellation, no-show, length of stay, ancillary spend, and flow-through', null, 1),
  ('36890810-ae5a-4baa-964e-540df49c929a', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '4eb7edba-81ac-43d7-b58c-1a8b416ff00d', 'concept'::public.curated_course_node_type, 'Commercial meetings, shared metrics, decision rights, test-and-learn backlog, tradeoffs, and forecast feedback', null, 2),
  ('6be0cf96-ac8b-4672-afba-9f3f0e257323', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Reputation, Reviews, Service Recovery, and Crisis Communication', 'Hospitality reputation is produced by real experiences and amplified by platforms, media, and word of mouth. Students learn to listen, respond, recover, and improve without manipulating the evidence guests depend on.', 10),
  ('9a382833-871d-497d-a337-07ddf64cd115', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6be0cf96-ac8b-4672-afba-9f3f0e257323', 'subtopic'::public.curated_course_node_type, 'Review and reputation intelligence', 'Students analyze rating distributions, volume, recency, text, themes, response patterns, and competitor context.', 0),
  ('7f8035b8-79d0-41db-ba7d-a044b856086b', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '9a382833-871d-497d-a337-07ddf64cd115', 'concept'::public.curated_course_node_type, 'Review sources, verified stays, sampling, recency, volume, score distribution, sentiment, topics, and language', null, 0),
  ('d6fc0766-184d-4ee1-9f7d-c12cd3d53f18', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '9a382833-871d-497d-a337-07ddf64cd115', 'concept'::public.curated_course_node_type, 'Operational root causes, expectations, property/outlet/segment differences, trends, alerts, and closed-loop ownership', null, 1),
  ('b715f6db-a5a1-44db-8ab0-04263c81b614', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '9a382833-871d-497d-a337-07ddf64cd115', 'concept'::public.curated_course_node_type, 'Benchmark comparability, platform rules, fake-review signals, incentives, moderation, and evidentiary limits', null, 2),
  ('6a12c8eb-1076-4952-8da3-e1a8e1f92a97', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6be0cf96-ac8b-4672-afba-9f3f0e257323', 'subtopic'::public.curated_course_node_type, 'Response and service recovery', 'This subtopic develops timely, human, privacy-aware responses that acknowledge experience, solve what can be solved, and feed operational learning.', 1),
  ('087f427d-8dcb-4b65-929f-9e7fbbb4e497', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6a12c8eb-1076-4952-8da3-e1a8e1f92a97', 'concept'::public.curated_course_node_type, 'Listen, acknowledge, apologize where appropriate, explain without defensiveness, resolve, follow up, and document', null, 0),
  ('a600a62a-baa8-42c6-80b2-d824a7c8f9a2', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6a12c8eb-1076-4952-8da3-e1a8e1f92a97', 'concept'::public.curated_course_node_type, 'Public versus private response, personal data, safety, discrimination, threats, charge disputes, legal escalation, and employee support', null, 1),
  ('5b1eb0c8-daac-4b9f-bf63-083833dab77d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6a12c8eb-1076-4952-8da3-e1a8e1f92a97', 'concept'::public.curated_course_node_type, 'Recovery authority, compensation guardrails, case routing, root-cause coding, learning review, and prevention', null, 2),
  ('656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6be0cf96-ac8b-4672-afba-9f3f0e257323', 'subtopic'::public.curated_course_node_type, 'Crisis and issues communication', 'Students prepare for sudden events that affect safety, trust, access, operations, employees, destinations, or brand meaning.', 2),
  ('4e2afcd2-01a3-446f-8a15-684eaeb30a2c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f', 'concept'::public.curated_course_node_type, 'Crisis team, stakeholder map, holding statement, facts, approvals, spokesperson, channels, accessibility, and cadence', null, 0),
  ('7029ed7c-7efa-497c-8482-89afdccc25fc', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f', 'concept'::public.curated_course_node_type, 'Safety, weather, cyber events, health, labor, discrimination, influencer incidents, operational disruption, and misinformation', null, 1),
  ('d566eed4-bcf8-464c-ac35-8d4360199ccc', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '656f3cd2-dcb1-4f16-b6cd-ddfda8c5d34f', 'concept'::public.curated_course_node_type, 'Speed versus certainty, empathy, rumor control, media monitoring, correction, recovery narrative, and after-action review', null, 2),
  ('0d0d1de8-bb81-460b-b0f4-11c27afccb24', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Marketing Analytics, Experimentation, Attribution, and ROI', 'Measurement should improve decisions, not merely decorate reports. Students build a metric system from business objective to guest behavior, financial outcome, causal evidence, and action.', 11),
  ('0b5272f9-ee28-4a49-9bde-58fb582dafca', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0d0d1de8-bb81-460b-b0f4-11c27afccb24', 'subtopic'::public.curated_course_node_type, 'Measurement architecture and funnel', 'Students define observable events and consistent metrics across awareness, consideration, booking, experience, retention, and advocacy.', 0),
  ('14b25a3a-f8b3-4b8d-9eb6-fa6ef29771e7', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0b5272f9-ee28-4a49-9bde-58fb582dafca', 'concept'::public.curated_course_node_type, 'Objective, KPI, diagnostic metric, dimension, event, source, owner, target, threshold, and decision rule', null, 0),
  ('21b7ce08-ca54-4abf-96cf-08ecbd1b2183', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0b5272f9-ee28-4a49-9bde-58fb582dafca', 'concept'::public.curated_course_node_type, 'Reach, frequency, engagement, sessions, qualified traffic, leads, booking starts, conversion, revenue, cancellation, and retention', null, 1),
  ('0109e82c-3a6e-4f71-ba29-54d53149b520', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0b5272f9-ee28-4a49-9bde-58fb582dafca', 'concept'::public.curated_course_node_type, 'Metric dictionary, UTM taxonomy, campaign naming, tag plan, data layer, QA, reconciliation, latency, and versioning', null, 2),
  ('3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0d0d1de8-bb81-460b-b0f4-11c27afccb24', 'subtopic'::public.curated_course_node_type, 'Economics and performance analysis', 'This subtopic connects media and campaign performance to contribution rather than stopping at impressions, clicks, or gross revenue.', 1),
  ('13fe4148-cb8d-42bd-8978-7dc916112cc9', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d', 'concept'::public.curated_course_node_type, 'CPM, CPC, cost per lead, cost per acquisition, ROAS, marketing ROI, contribution, payback, and lifetime value', null, 0),
  ('feec25ae-7b86-4874-a3b2-16327a9cbfc7', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d', 'concept'::public.curated_course_node_type, 'Budget, marginal return, saturation, diminishing returns, portfolio allocation, scenario, sensitivity, and opportunity cost', null, 1),
  ('b1d8d5ee-ae64-4dd5-bfbc-80a640b9b44f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '3fda4a3a-7ce8-4ec3-b5dc-4ef33cc2a17d', 'concept'::public.curated_course_node_type, 'Segment, channel, market, creative, device, cohort, property, outlet, and period analysis', null, 2),
  ('6d6ef760-be6d-477a-887e-88b54205b15f', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '0d0d1de8-bb81-460b-b0f4-11c27afccb24', 'subtopic'::public.curated_course_node_type, 'Experiments, attribution, and incrementality', 'Students distinguish correlation from causation and interpret platform attribution with appropriate skepticism.', 2),
  ('80fca97e-c271-4fa1-b1ba-ffa09b8f0728', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6d6ef760-be6d-477a-887e-88b54205b15f', 'concept'::public.curated_course_node_type, 'A/B and multivariate tests, randomized holdouts, geo tests, pre/post, matched markets, sample size, power, and guardrails', null, 0),
  ('40921dc7-2f6e-41b5-affc-6e7b47bde1d5', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6d6ef760-be6d-477a-887e-88b54205b15f', 'concept'::public.curated_course_node_type, 'Last-click, rules-based, data-driven, multi-touch, view-through, modeled events, lookback windows, and walled gardens', null, 1),
  ('bf8c85b1-6cab-4357-aa7d-fae14bc884cb', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '6d6ef760-be6d-477a-887e-88b54205b15f', 'concept'::public.curated_course_node_type, 'Incremental lift, selection bias, spillover, novelty, seasonality, statistical versus managerial significance, and replication', null, 2),
  ('b43403db-4520-44c1-b9bd-f93816e90764', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Ethics, Privacy, Responsible AI, Sustainability, and Trust', 'Marketing power carries duties to guests, employees, communities, partners, and the brand. Students evaluate whether a tactic is lawful, truthful, inclusive, secure, environmentally credible, and worthy of trust—not merely whether it performs.', 12),
  ('b655baa9-cc8d-419b-9eae-41da4adff42c', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b43403db-4520-44c1-b9bd-f93816e90764', 'subtopic'::public.curated_course_node_type, 'Truthful and fair marketing', 'Students apply U.S. truth-in-advertising principles to claims, endorsements, reviews, prices, promotions, scarcity, and targeting.', 0),
  ('ffbf0e37-16c3-4714-9710-19893e03c362', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b655baa9-cc8d-419b-9eae-41da4adff42c', 'concept'::public.curated_course_node_type, 'Claim substantiation, clear and conspicuous disclosures, material connections, native ads, endorsements, and testimonials', null, 0),
  ('949c56b7-ac69-45e4-b4cf-4e267c3f0241', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b655baa9-cc8d-419b-9eae-41da4adff42c', 'concept'::public.curated_course_node_type, 'FTC Consumer Review Rule, fake or AI-generated reviews, review suppression, incentives, insider reviews, and threats', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a19a7114-63cc-4843-affc-ff3501952991', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b655baa9-cc8d-419b-9eae-41da4adff42c', 'concept'::public.curated_course_node_type, 'Dark patterns, false urgency, misleading availability, hidden conditions, drip pricing, vulnerable audiences, and documentation', null, 2),
  ('b6686f28-9d9d-423d-9ab2-875883e90fb4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b43403db-4520-44c1-b9bd-f93816e90764', 'subtopic'::public.curated_course_node_type, 'Privacy, security, and data governance', 'This subtopic teaches data minimization, purpose limitation, access control, retention, and vendor oversight in a changing legal environment.', 1),
  ('17934b43-abd2-47b5-8486-69ffe8b44ec9', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b6686f28-9d9d-423d-9ab2-875883e90fb4', 'concept'::public.curated_course_node_type, 'First-, second-, and third-party data; consent; notice; preference; deletion; access; portability; and opt-out concepts', null, 0),
  ('ed8e1b05-09d3-4282-8375-02703a8509ef', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b6686f28-9d9d-423d-9ab2-875883e90fb4', 'concept'::public.curated_course_node_type, 'Sensitive data, location, children, biometrics, accessibility needs, payment, identity, loyalty, and employee information', null, 1),
  ('c98b3642-86fc-4ca5-a0ff-e49908cae6cb', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b6686f28-9d9d-423d-9ab2-875883e90fb4', 'concept'::public.curated_course_node_type, 'Data inventory, lawful purpose, minimization, retention, role-based access, vendor contracts, breach response, and state-law review', null, 2),
  ('cc8e6573-3b8a-4556-8df8-6984a8faf1e0', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'b43403db-4520-44c1-b9bd-f93816e90764', 'subtopic'::public.curated_course_node_type, 'Responsible AI and credible sustainability', 'Students use AI and sustainability claims with accountable human judgment, evidence, testing, and transparency.', 2),
  ('df8a1f1a-2f58-4c18-b959-7ce34c5ce9c4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'cc8e6573-3b8a-4556-8df8-6984a8faf1e0', 'concept'::public.curated_course_node_type, 'Generative content, translation, personalization, recommendations, forecasting, social listening, synthetic media, and agents', null, 0),
  ('2230deda-01c1-4174-8659-5698ab03949d', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'cc8e6573-3b8a-4556-8df8-6984a8faf1e0', 'concept'::public.curated_course_node_type, 'Accuracy, hallucination, bias, representational harm, intellectual property, disclosure, prompt/data leakage, monitoring, and human approval', null, 1),
  ('7cfe818c-ff79-4cfd-83d2-997c2cfc53d4', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', 'cc8e6573-3b8a-4556-8df8-6984a8faf1e0', 'concept'::public.curated_course_node_type, 'Environmental and social claims, boundaries, baselines, materiality, substantiation, greenwashing, community impact, and accessible benefits', null, 2),
  ('598d1376-2f54-43b2-a081-b3b021f5a388', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', null, 'topic'::public.curated_course_node_type, 'Integrated Hospitality Marketing Plan and Campaign Execution', 'The capstone integrates analysis, choice, creative strategy, channels, operations, economics, governance, measurement, and learning. The plan is a decision system with owners and contingencies—not a slide deck of disconnected tactics.', 13),
  ('11cd3cda-038c-4b5f-b5f9-4a7a8aaf44e0', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '598d1376-2f54-43b2-a081-b3b021f5a388', 'subtopic'::public.curated_course_node_type, 'Situation, objectives, and strategy', 'Students synthesize internal, customer, competitor, channel, and environmental evidence into a focused strategic diagnosis.', 0),
  ('e5ea14cd-647c-4301-9c1e-84de92562e14', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11cd3cda-038c-4b5f-b5f9-4a7a8aaf44e0', 'concept'::public.curated_course_node_type, 'Business context, performance baseline, research insight, market opportunity, problem statement, and assumptions', null, 0),
  ('38a1cc51-4874-4118-b306-557ea5e6663e', 'a2b3c4d5-6e7f-4a17-8b96-0c1d2e3f4a07', '11cd3cda-038c-4b5f-b5f9-4a7a8aaf44e0', 'concept'::public.curated_course_node_type, 'SMART objectives, target segments, positioning, value proposition, offer, competitive response, and strategic choices', null, 1),
